export interface Player {
  id: string;
  name: string;
  position: 'QB' | 'RB' | 'WR' | 'TE' | 'K' | 'DST';
  team: string;
  tier: 1 | 2 | 3 | 4;
  baseValue: number;
  estimatedValue: number;
  /**
   * What our own model says, kept even when an imported ranking has replaced
   * the value everything else reads. Facts and opinions stay distinguishable:
   * the board can show whose number it is showing.
   */
  modelValue: number;
  /**
   * Where *we* rank him, kept whatever is driving the board.
   *
   * The exact counterpart of `modelValue`, and it was missing. `adp` is the
   * rank in force, which after "Use consensus" — the recommended way to run
   * the night — is the market's. Two panels printed it labelled as ours: the
   * bargain board's `title="Our rank"` and the profile's "our board #21"
   * beside "consensus #14". Both were then comparing the market with the
   * market and reporting a disagreement nobody held.
   *
   * The same trap `getBargains` was already pulled out of: it reads
   * `modelValue` rather than the live price so that pressing the button cannot
   * re-derive the disagreement against itself. The ranks beside those dollars
   * needed the same treatment and did not get it.
   */
  modelRank: number;
  /** Present only when an imported ranking is overriding this player. */
  customRanking?: RankingOverride;
  /**
   * Whether the money is buying this player, or the snake is.
   *
   * The mask `pricePool` used, read back rather than derived again — which
   * players are for sale decides prices, what inflation is measured over and
   * when the auction is finished, and every one of those working it out
   * separately is a second definition that can disagree on the only night it
   * matters. It rides on the player object rather than arriving as a card
   * prop: the board mounts sixty memoised cards and a prop that changes with
   * the sheet would re-render all of them.
   *
   * True for everybody when the whole board is auctioned, because then there
   * is no sheet to be off.
   */
  onSheet: boolean;
  /**
   * Whether `onSheet` is a stated list or the model's guess at one.
   *
   * With a size typed into the settings panel but no list imported, the mask is
   * simply our own best N by surplus. Telling 568 players they are "not on the
   * auction sheet" is then stating as fact something nobody has said — and it
   * moves: removing a 60-name sheet leaves 60 players still marked, only 40 of
   * whom were ever on it. A guess and a fact have to read differently.
   */
  sheetIsStated: boolean;
  projectedPoints: number;
  adp: number; // Average Draft Position
  injuryRisk: 'LOW' | 'MEDIUM' | 'HIGH';
  strengthOfSchedule?: number; // 1-10 scale
  valueOverReplacement: number; // VORP
  upside: number; // Ceiling projection
  floor: number; // Floor projection
  consistency: number; // Week-to-wave variance (1-10)
  byeWeek: number;
  ageRisk: 'LOW' | 'MEDIUM' | 'HIGH';
  targetShare?: number; // Expected target/touch share %
  redZoneShare?: number; // Red zone opportunity %
  // Enhanced real data fields
  age?: number;
  experience?: number; // Years in NFL
  lastSeasonGames?: number;
  careerGames?: number;
  injuryHistory?: string[]; // List of past injuries
  contractStatus?: 'SECURE' | 'EXPIRING' | 'ROOKIE' | 'FRANCHISE_TAG';
  coachingStability?: 'STABLE' | 'NEW_COACH' | 'NEW_SYSTEM';
  offensiveLineRank?: number; // 1-32 team rank
  defensiveStrengthVsPosition?: number; // Opponent strength vs position
  weatherConcerns?: boolean; // Dome vs outdoor team
  playoffSchedule?: 'EASY' | 'MODERATE' | 'DIFFICULT';
  handcuffValue?: number; // Value if starter injured (0-100)
  primaryBackup?: string; // Name of primary backup
  competitionLevel: 'LOCKED_STARTER' | 'MINOR_COMPETITION' | 'TIMESHARE' | 'COMMITTEE';
  teamPaceRank?: number; // Team pace ranking (1-32)
  redZoneTouchesLastSeason?: number;
  snapPercentage?: number; // Expected snap %
  recentTrends: 'RISING' | 'STABLE' | 'DECLINING';
  fantasyRelevantWeeks?: number; // Weeks likely to be fantasy relevant
  floorWeeks?: number; // Number of weeks hitting floor
  ceilingWeeks?: number; // Number of weeks hitting ceiling
  /** Where each headline number sits among players at the same position, 0-100. */
  percentiles?: Record<string, number>;
  pointsPerGame?: number;
  expectedGames?: number;
  /** Games of tape behind the projection. See `modelTrust.ts`. */
  gamesObserved?: number;
  /**
   * The market drafts him and the pool has never heard of him.
   *
   * He carries no projection, so every number on his card is absent rather
   * than zero, and he is outside the arithmetic that sets replacement level.
   * True only for entries built from the market snapshot's `absent` list.
   */
  marketOnly?: boolean;
  usage?: PlayerUsage | null;
  teamContext?: TeamContext | null;
  durability?: Durability;
  competition?: DepthCompetition;
  market?: MarketRead;
  breakoutSeason?: number | null;
  draftCapital?: { year: number; round: number; pick: number; team: string } | null;
  /** Team defense season totals. Present only for DST entries. */
  defense?: {
    sacks: number;
    interceptions: number;
    fumbleRecoveries: number;
    touchdowns: number;
    safeties: number;
    pointsAllowedPerGame: number | null;
  };
  isDrafted: boolean;
  draftedBy?: string;
  draftCost?: number;
  pickNumber?: number;
}

