export type PlayerPosition = 'QB' | 'RB' | 'WR' | 'TE' | 'K' | 'DST';

/** Roster counts by position. Every draftable position needs a key here — a
 *  missing one turns `roster[position]++` into NaN and poisons depth scoring. */
export type RosterCounts = Record<PlayerPosition, number>;

export interface BidRejection {
  ok: false;
  /** Machine-readable so the UI can decide how loudly to complain. */
  code:
    | 'unknown-player'
    | 'unknown-team'
    | 'already-drafted'
    | 'invalid-amount'
    | 'insufficient-funds'
    | 'roster-full'
    | 'position-full'
    // The snake half of the draft. A free pick has no money to be wrong about,
    // so the only two ways it can be illegal beyond the roster rules are being
    // taken while the auction is still running and being taken out of turn.
    | 'not-in-snake'
    | 'not-your-turn';
  message: string;
}

export type BidCheck = { ok: true } | BidRejection;

/**
 * Which half of the draft a transaction belongs to.
 *
 * This league auctions a commissioner's sheet of 50-100 players and then fills
 * every remaining roster spot by serpentine snake draft — roughly 60 picks
 * bought with money and 140 taken for nothing.
 */
export type DraftPhase = 'auction' | 'snake';

/**
 * One transaction in the pick log.
 *
 * `phase` is stored rather than derived, and that is not a breach of the
 * pick-log-stores-nothing-derived rule: it is a fact about the transaction,
 * exactly like the price. It cannot be recovered afterwards — marking one more
 * player unsold, or putting one back up, moves where the auction ended, and
 * every pick already made would silently reclassify. What stays derived is
 * whose turn it is, which is computed from the log and the order.
 *
 * `cost` is absent on a snake pick and must stay absent rather than become 0:
 * zero reads as "bought for nothing", which is a different claim and poisons
 * premium, surplus, inflation and every grade downstream.
 */
export interface DraftPick {
  playerId: string;
  teamId: string;
  cost?: number;
  phase: DraftPhase;
  /**
   * Which seat on the serpentine board a snake pick consumed.
   *
   * Stored for the same reason the phase is: it is a fact about the
   * transaction, and it cannot be recovered afterwards. Without it, whose turn
   * it was had to be reconstructed by replaying every earlier snake pick
   * through the order in force *now* — so reordering the board mid-draft
   * re-attributed picks already taken to whichever teams the new order put in
   * those seats, and handed the clock to a team that was already full. With the
   * seat recorded, a reorder can only change who sits in the seats still empty,
   * which is exactly what the panel promises.
   */
  slot?: number;
}

/**
 * An amendment to one entry in the pick log.
 *
 * The three things that get misheard across a table: which player, which team,
 * and how much. Every field is optional because a correction is an amendment
 * and not a replacement — the fields left out keep what the log already says.
 *
 * The phase is deliberately not among them. It is a fact about the transaction
 * rather than a label on it: relabelling an auction sale as a snake pick would
 * unspend money the room actually spent, and relabelling a snake pick as a sale
 * would invent a price nobody paid. When the wrong half is recorded — which
 * takes drafting a player the sheet never held — the honest repair is to undo
 * back to it, because that is the only thing that can put the sheet back where
 * it was.
 */
export interface PickCorrection {
  playerId?: string;
  teamId?: string;
  cost?: number;
}

/**
 * What a correction did, or would do.
 *
 * The same shape `importDraft` reports, and for the same reason: replaying an
 * amended log can leave a later pick illegal — a raised price that busts a
 * budget, a player who is now taken twice — and a pick that no longer replays
 * is counted rather than dropped in silence.
 */
export type CorrectionResult =
  | { ok: true; restored: number; skipped: number }
  | { ok: false; reason: string };

/** A pick a correction would cost, named so the room can be asked first. */
export interface InvalidatedPick {
  /** Its place in the draft, counting from one. */
  pickNumber: number;
  player: string;
  team: string;
  /** The engine's own words for why it would no longer replay. */
  reason: string;
}

/** What a correction would do, answered before anything is applied. */
export type CorrectionCheck =
  | { ok: true; restored: number; skipped: number; invalidated: InvalidatedPick[] }
  | { ok: false; reason: string };

/** One seat on the serpentine board: who picks, and where it falls. */
export interface SnakeSlot {
  team: Team;
  /** Round on the board, counting from one. */
  round: number;
  /** Seat within the round, counting from one and always left-to-right. */
  pick: number;
  /** Which snake pick of the whole draft this is, counting from one. */
  overall: number;
  /** The seat's index on the endless serpentine board, counting from zero. */
  slot: number;
}

