/** What the room is doing with its money, derived entirely from the pick log. */
export interface MarketState {
  inflation: number;
  premium: number | null;
  moneyLeft: number;
  valueLeft: number;
  scarcity: Array<{
    position: PlayerPosition;
    gone: number;
    total: number;
    tierOneLeft: number;
    /** What the room paid against our list at this position, once two have sold. */
    premium: number | null;
    sold: number;
    /** Points between the best player left here and the fifth: the cost of waiting. */
    cliff: number;
  }>;
}

/**
 * The bounds inflation is clamped to.
 *
 * Exported because the meter that draws it has to know where its ends are: a
 * bar drawn 0.6 to 1.8 while the engine clamps to something else is a bar that
 * lies about being pinned. One definition, read by both.
 */
export const INFLATION_BOUNDS = { min: 0.6, max: 1.8 } as const;

/**
 * Where the inflation number came from.
 *
 * A multiplier nobody can interrogate is not an edge — it is a number to be
 * talked out of at the worst moment. Every input that produced it is reported
 * beside it, including the two ways it can stop being a live reading: the
 * clamp, and the snake phase, where it is held at 1 because no money moves.
 */
export interface InflationBasis {
  /** The multiplier itself, exactly what every adjusted price on the board uses. */
  inflation: number;
  /** Dollars unspent, less whatever the reserve holds back. */
  moneyLeft: number;
  /** List value of everything still for sale. */
  valueLeft: number;
  /** Slots the reserve holds a dollar back for. Zero whenever a snake fills the rest. */
  openSlots: number;
  /** money over value before the clamp, so a pinned meter can say it is pinned. */
  raw: number;
  /** Which end of the clamp the raw ratio hit, if either. */
  clamped: 'floor' | 'ceiling' | null;
  /** True through the snake, where the ratio is frozen rather than measured. */
  frozen: boolean;
  /** Players the money is still chasing, and how many it ever was. */
  forSaleLeft: number;
  forSaleTotal: number;
}

/**
 * A list price restated at the room's inflation, for any player on the board.
 *
 * Handed out as a closure rather than written onto the Player object, and that
 * is not a style choice. The board mounts sixty memoised cards whose props are
 * stable element references, so they do not re-render on a pick at all; an
 * adjusted price is a number that changes on *every* pick, and putting it on
 * the player — or passing it as a card prop — would re-render all sixty of them
 * each time, each one re-resolving identity and team colours. Measured once at
 * 4.3 seconds to nominate, and it is invisible to every test.
 *
 * So it goes where a price is actually being decided: the stage, the table's
 * value column, and the market panel.
 */
export interface PriceAdjuster {
  inflation: number;
  frozen: boolean;
  /** Whole dollars. Off-sheet players are unmoved: nobody is bidding on them. */
  price(player: Player): number;
}

/**
 * One opponent who could still take this player off you, and how far they can go.
 *
 * `ceiling` is a *rule*, not a guess: it comes from `spendableFor`, the same
 * call `validateBid` runs, so a number shown beside the bid box cannot be one
 * the engine would then reject. That was the failure this exists to prevent.
 *
 * After the reserve change it is essentially a team's whole remaining budget,
 * which is higher than anybody expects it to be, and that is the point — the
 * room reading as poorer than it is cost real players.
 *
 * What a rational manager would *actually* go to is a different claim entirely
 * and is not here: it lives in `draftAdvisor`, in the estimate register.
 */
export interface RivalBidder {
  team: Team;
  /** The most the rules let them commit to this one player. */
  ceiling: number;
  /** What the reserve withholds from them. Zero whenever the snake fills the rest. */
  held: number;
  /** Starting slots this player would fill for them, through the league's own lineup. */
  need: number;
  /** How many of the position they already carry. */
  have: number;
  /** Whether this is the team the owner marked as theirs. */
  mine: boolean;
  /**
   * Whether they have room for him at all.
   *
   * A team with a full roster or a full position is not a bidder at any price,
   * so it is never a rival. It is still worth reporting for the owner's own
   * team, which is why this is a flag rather than an exclusion: folding that
   * case into the blocked *count* told the owner to mark a team as theirs when
   * they already had, and counted them among their own opponents.
   */
  canRoster: boolean;
}

/** Who is left in the bidding on the player on the block. */
export interface BidCompetition {
  /** The bid being beaten. Zero before anybody has said a number. */
  currentBid: number;
  /** Opponents who can legally beat it, richest first. */
  rivals: RivalBidder[];
  /** The owner's own ceiling, when a team has been marked as theirs. */
  mine: RivalBidder | null;
  /** Teams with no room for him at all: they cannot bid at any price. */
  blocked: number;
  /** Teams with room whose money cannot reach the current bid. */
  outspent: number;
}

/**
 * How fast a position is leaving the board.
 *
 * Supply, so it counts both halves of the draft: a receiver taken in the snake
 * is exactly as unavailable as one bought for $40, and waiting for him is
 * exactly as impossible. Nothing here is money, so nothing here excludes a
 * free pick.
 */
export interface PositionRun {
  position: PlayerPosition;
  /** Picks at this position inside the window, either half. */
  taken: number;
  /** How many picks the window actually covers; fewer than asked for early on. */
  window: number;
  /** Share of the window that was this position. */
  share: number;
  /** Players above replacement still on the board here. */
  left: number;
  /** How many of those there were when the window opened. */
  leftBefore: number;
}

/**
 * The shelf about to empty at a position, and the step down off it.
 *
 * Tiers are the shape of a position's board: inside one, players are
 * interchangeable enough that waiting costs nothing, and the moment the last of
 * them goes the next name is materially worse. That step is where money is won
 * and lost, so it is reported in both currencies — points, which every player
 * has, and dollars, which only players being auctioned have.
 *
 * The counts include snake picks, because a tier empties however a player left.
 * The dollar step does not survive a player who is not for sale: his list price
 * is the $1 floor rather than a price anybody would pay, so subtracting it
 * would invent a cliff.
 */
export interface TierBreak {
  position: PlayerPosition;
  /** The best tier with anybody left in it: the one currently being drafted out of. */
  tier: number;
  /** How many of it remain. */
  left: number;
  /** How many it started with. */
  started: number;
  /** The last one, when exactly one is left — the player the warning is about. */
  last: Player | null;
  /**
   * Projected points from the worst of this tier to the best of the next, or
   * null when there is no tier below.
   *
   * Nullable rather than zero, because those are different claims: "there is no
   * drop off this shelf" and "there is no shelf below this one" read the same
   * as `−0 pts` and only one of them is ever true.
   */
  pointStep: number | null;
  /** The same step in dollars, or null when either side is not being auctioned. */
  dollarStep: number | null;
}

export interface DraftState {
  players: Player[];
  teams: Team[];
  draftedCount: number;
  totalPlayers: number;
  currentPick: number;
}

export interface SnakeDraftPlayer {
  id: string;
  name: string;
  position: 'QB' | 'RB' | 'WR' | 'TE' | 'K' | 'DST';
  team: string;
  tier: 1 | 2 | 3 | 4 | 5;
  baseValue: number;
  estimatedValue: number;
  projectedPoints: number;
  adp: number;
  injuryRisk: 'LOW' | 'MEDIUM' | 'HIGH';
  strengthOfSchedule: number;
  valueOverReplacement: number;
  upside: number;
  floor: number;
  consistency: number;
  byeWeek: number;
  ageRisk: 'LOW' | 'MEDIUM' | 'HIGH';
  targetShare: number;
  redZoneShare: number;
  age: number;
  experience: number;
  lastSeasonGames: number;
  careerGames: number;
  injuryHistory: string[];
  contractStatus: 'SECURE' | 'EXPIRING' | 'ROOKIE' | 'FRANCHISE_TAG';
  coachingStability: 'STABLE' | 'NEW_COACH' | 'NEW_SYSTEM';
  offensiveLineRank: number;
  defensiveStrengthVsPosition: number;
  weatherConcerns: boolean;
  playoffSchedule: 'EASY' | 'MODERATE' | 'DIFFICULT';
  handcuffValue: number;
  primaryBackup?: string;
  competitionLevel: 'LOCKED_STARTER' | 'MINOR_COMPETITION' | 'TIMESHARE' | 'COMMITTEE';
  teamPaceRank: number;
  redZoneTouchesLastSeason: number;
  snapPercentage: number;
  recentTrends: 'RISING' | 'STABLE' | 'DECLINING';
  fantasyRelevantWeeks: number;
  floorWeeks: number;
  ceilingWeeks: number;
  // Enhanced snake draft specific analytics
  breakoutPotential: number;
  regressionRisk: number;
  rookieProjection?: number;
  coachingFit: number;
  opportunityRank: number;
  depthChart: number;
  sleeper: boolean;
  bustRisk: number;
  weeklyVolatility: number;
  positionalScarcity: number;
  handcuffRecommendation: string;
  isDrafted: boolean;
  draftedBy?: string;
  pickNumber?: number;
}

/**
 * The league the shipped pool was priced for.
 *
 * Read from pool.json rather than restated, so that regenerating the pool for a
 * different shape moves the client's default with it. Everything downstream
 * reads `this.league`, which starts here and can be changed at runtime.
 */
const POOL_LEAGUE: LeagueShape = leagueShape(
  (poolData as { league?: Partial<LeagueShape> }).league ?? DEFAULT_LEAGUE
);

/**
 * The chosen league, kept apart from the pick log.
 *
 * It is a league-wide fact rather than a per-person preference, so it does not
 * belong in `use-draft-preferences`; but it is also not a pick, and the pick
 * log deliberately stores nothing derived. Its own key keeps both rules intact.
 */
const LEAGUE_STORAGE_KEY = 'draft-vault:league:v1';

/**
 * That somebody has actually said what league this is.
 *
 * Deliberately its own key rather than the presence of the league itself:
 * `writeStoredLeague` removes that key when the shape matches the pool's, since
 * there is nothing to remember — which makes "a league is stored" mean "the
 * league differs from the default", not "the league has been confirmed". They
 * are different questions, and the one worth gating a first run on is the
 * second: a league that happens to match the defaults still has to have been
 * looked at, because the defaults are full PPR with no flex and almost nobody
 * plays that.
 */
const LEAGUE_CONFIRMED_KEY = 'draft-vault:league-confirmed:v1';
/**
 * Whether the overrides in force were *derived* rather than stated.
 *
 * Its own key for the same reason `LEAGUE_CONFIRMED_KEY` is: it answers a
 * different question from the overrides themselves. An imported CSV carries
 * dollar values somebody chose, and nothing may recompute them. The market
 * board carries dollar values read off our own surplus curve, so the moment
 * that curve moves — which is exactly what importing a sheet does — they are
 * stale and have to be derived again.
 *
 * Reading it off the overrides' `notes` instead would work until somebody's
 * CSV had a notes column saying "consensus", and the cost of that collision is
 * silently replacing their stated values with ours.
 */
const MARKET_BOARD_KEY = 'draft-vault:market-board:v1';

/**
 * That this browser has been opened on the league the build is for.
 *
 * A one-time marker in the idiom `LEAGUE_CONFIRMED_KEY` already uses, and it is
 * the whole difference between a *default* and an *action*. `HOME_LEAGUE`
 * settles what an empty browser prices at; the sheet and the market board are
 * two more things a fresh browser would otherwise have to be told, and seeding
 * them on every load would mean a sheet the owner cleared coming back, and a
 * market board he turned off turning itself on. Seeded once, then never again —
 * so every later change is his and sticks.
 */
const HOME_SEEDED_KEY = 'draft-vault:home-defaults:v1';

/**
 * Where a player we cannot rank sits in our own ordering: after everyone.
 *
 * Past any real pool size, so it stays behind the whole board however deep the
 * pool grows. Never printed — `marketOnly` makes every panel show a dash.
 */
const MARKET_ONLY_RANK = 9999;

const readStoredLeague = (): LeagueShape => {
  try {
    const raw = localStorage.getItem(LEAGUE_STORAGE_KEY);
    if (!raw) return HOME_LEAGUE;
    return normaliseLeague(leagueShape(JSON.parse(raw) as Partial<LeagueShape>));
  } catch {
    // Unparseable or unavailable storage falls back to the league this build is
    // for, which is always a valid one — and, unlike the shape the pool file
    // happens to have been priced at, is the one being played.
    return HOME_LEAGUE;
  }
};

const writeStoredLeague = (league: LeagueShape): void => {
  try {
    // Nothing to remember when it matches the build's own league, so "a league
    // is stored" keeps meaning "somebody changed it" — which is the question
    // `LEAGUE_CONFIRMED_KEY` is deliberately not answering.
    if (sameLeague(league, HOME_LEAGUE)) localStorage.removeItem(LEAGUE_STORAGE_KEY);
    else localStorage.setItem(LEAGUE_STORAGE_KEY, JSON.stringify(league));
  } catch {
    /* storage unavailable — the league simply won't be remembered */
  }
};

/**
 * Somebody else's rankings, laid over ours.
 *
 * An import is an opinion — the whole point of it is to disagree with the
 * model — so it is stored apart from both the pick log and the league, and the
 * model's own number survives underneath it on every player.
 */
const RANKINGS_STORAGE_KEY = 'draft-vault:custom-rankings:v1';

/**
 * The commissioner's sheet: which players the money is actually buying.
 *
 * A sheet *size* is a guess at this list — the best N by surplus, as though the
 * commissioner had picked ours. He picked off consensus rankings, so a player
 * we price at $2 is on it and a player we price at $30 is not. Kept in its own
 * key for the same reason the league is: it is a league-wide fact rather than a
 * per-person preference, and it is not a pick, so it cannot live in the pick
 * log — which stores nothing derived.
 *
 * `unsold` is the sheet player nobody bid a dollar on. He is marked rather than
 * struck off, because striking him off would shorten the sheet, and the sheet's
 * length is the league's `auctionSheetSize` — re-pricing the board mid-auction
 * and, since `sameLeague` is what lets a saved draft replay, refusing to
 * restore the draft being played.
 */
const SHEET_STORAGE_KEY = 'draft-vault:auction-sheet:v1';

/** The sheet as it is stored: who is being auctioned, and who went unsold. */
export interface StoredSheet {
  ids: string[];
  unsold: string[];
  /**
   * What `auctionSheetSize` was before the sheet pinned it.
   *
   * Removing a sheet has to put the league back where it found it, and nothing
   * else records that. Without it, applying a 60-name list to the default whole
   * board and then removing it leaves a permanent 60-player partial auction
   * nobody chose — the top of the board roughly doubles, 568 players sit at $1
   * wearing a snake badge, and the only way out is a league change that throws
   * the draft away.
   */
  priorSize?: number | null;
  /**
   * The share of the paste that did not resolve, kept rather than recomputed.
   *
   * It is a fact about the import and the text it came from is gone, so it
   * cannot be recovered afterwards — and it is exactly the fact that decides
   * whether the board is priced for the auction being held. A paste that loses
   * a chunk out of the middle leaves the top twenty pricing perfectly sensibly
   * with `auctionSheetSize` quietly forty rather than sixty.
   */
  loss?: number | null;
}

const EMPTY_SHEET = (): StoredSheet => ({ ids: [], unsold: [] });

const readStoredSheet = (): StoredSheet => {
  try {
    const raw = localStorage.getItem(SHEET_STORAGE_KEY);
    const parsed = raw ? (JSON.parse(raw) as Partial<StoredSheet>) : null;
    if (!parsed || !Array.isArray(parsed.ids)) return EMPTY_SHEET();
    return {
      ids: parsed.ids.filter((id): id is string => typeof id === 'string'),
      unsold: Array.isArray(parsed.unsold)
        ? parsed.unsold.filter((id): id is string => typeof id === 'string')
        : [],
      priorSize: typeof parsed.priorSize === 'number' ? parsed.priorSize : null,
      loss: typeof parsed.loss === 'number' ? parsed.loss : null,
    };
  } catch {
    return EMPTY_SHEET();
  }
};

const writeStoredSheet = (sheet: StoredSheet): void => {
  try {
    if (!sheet.ids.length) localStorage.removeItem(SHEET_STORAGE_KEY);
    else localStorage.setItem(SHEET_STORAGE_KEY, JSON.stringify(sheet));
  } catch {
    /* storage unavailable — the sheet simply won't survive a reload */
  }
};

/**
 * The draft a reset threw away.
 *
 * Reset sits next to Undo in the toolbar and used to be one unrecoverable
 * click: the pick log was deleted outright. Since the pick log is the only
 * shared fact, keeping the last one aside makes a reset undoable — which
 * matters most on the night, when the draft in progress is the only copy of an
 * afternoon's work.
 */
const CLEARED_STORAGE_KEY = 'draft-vault:cleared-draft:v1';

/**
 * When the record last left this browser, and what it looked like then.
 *
 * The draft lives in one profile on one machine, and on the night there is no
 * server: a cleared profile, a crashed tab or a dead laptop takes the whole
 * afternoon with it. The only defence is a copy somewhere else, and the only
 * thing that reliably fails is remembering to make one while an auction is
 * running. So the exposure is measured rather than left to memory.
 *
 * It is stored rather than held in memory because a reload must not report the
 * record as freshly saved when it is not: the mark describes the copy the owner
 * actually holds, and a page refresh does not make one.
 */
const EXPORT_MARK_KEY = 'draft-vault:export-mark:v1';

/** The last time the whole draft was handed to something that is not this browser. */
/** The part of a mark that describes a particular text, rather than a moment. */
/**
 * What came of putting an undone pick back.
 *
 * A refusal is a result rather than a null, because the entry has already left
 * the stack by the time it is known: reporting nothing would lose the pick and
 * leave the room looking unchanged.
 */
export type RedoOutcome =
  | { ok: true; player: Player; team: Team; cost: number | null }
  | { ok: false; reason: string };

/** The part of a mark that describes a particular text, rather than a moment. */
export interface ExportSnapshot {
  picks: number;
  fingerprint: string;
}

export interface ExportMark {
  /** When, as an ISO stamp. */
  savedAt: string;
  /**
   * How it left.
   *
   * `file` covers a file arriving as well as leaving: a draft loaded from one
   * is a draft that demonstrably exists in a file, which is the only claim this
   * mark makes.
   */
  kind: 'file' | 'clipboard';
  /** Picks in the log at that moment. */
  picks: number;
  /**
   * A fingerprint of the log that went out.
   *
   * A count alone cannot answer the question. Undo the last pick and re-record
   * it correctly and the log is the same length and a different draft; correct
   * a price and it is the same length again. The fingerprint says "different"
   * where a count says "unchanged", and the two together say how far.
   */
  fingerprint: string;
}

const readStoredMark = (): ExportMark | null => {
  try {
    const raw = localStorage.getItem(EXPORT_MARK_KEY);
    const saved = raw ? (JSON.parse(raw) as Partial<ExportMark>) : null;
    if (!saved || typeof saved.fingerprint !== 'string') return null;
    return {
      savedAt: typeof saved.savedAt === 'string' ? saved.savedAt : new Date().toISOString(),
      kind: saved.kind === 'clipboard' ? 'clipboard' : 'file',
      picks: typeof saved.picks === 'number' ? saved.picks : 0,
      fingerprint: saved.fingerprint,
    };
  } catch {
    return null;
  }
};

const writeStoredMark = (mark: ExportMark): void => {
  try {
    localStorage.setItem(EXPORT_MARK_KEY, JSON.stringify(mark));
  } catch {
    /* storage unavailable — the exposure count simply restarts on reload */
  }
};

/**
 * Who the other eleven teams actually are.
 *
 * Deliberately not part of `LeagueShape`: that is the set of facts prices are
 * derived from, and `sameLeague` compares it to decide whether a draft can
 * survive a change. Renaming a team changes nothing about what a player is
 * worth, so putting names in there would throw the draft away over a typo.
 */
const ROSTER_STORAGE_KEY = 'draft-vault:teams:v1';

interface StoredTeams {
  names?: Record<string, string>;
  /** Which team is the person using this app. */
  mine?: string | null;
}

const readStoredTeams = (): StoredTeams => {
  try {
    const raw = localStorage.getItem(ROSTER_STORAGE_KEY);
    const parsed = raw ? (JSON.parse(raw) as StoredTeams) : null;
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch {
    return {};
  }
};

const writeStoredTeams = (value: StoredTeams): void => {
  try {
    if (!Object.keys(value.names ?? {}).length && !value.mine) {
      localStorage.removeItem(ROSTER_STORAGE_KEY);
    } else {
      localStorage.setItem(ROSTER_STORAGE_KEY, JSON.stringify(value));
    }
  } catch {
    /* storage unavailable — names simply will not be remembered */
  }
};

const readStoredOverrides = (): Record<string, RankingOverride> => {
  try {
    const raw = localStorage.getItem(RANKINGS_STORAGE_KEY);
    const parsed = raw ? (JSON.parse(raw) as Record<string, RankingOverride>) : null;
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch {
    return {};
  }
};

const writeStoredOverrides = (overrides: Record<string, RankingOverride>): void => {
  try {
    if (!Object.keys(overrides).length) localStorage.removeItem(RANKINGS_STORAGE_KEY);
    else localStorage.setItem(RANKINGS_STORAGE_KEY, JSON.stringify(overrides));
  } catch {
    /* storage unavailable — the import simply won't survive a reload */
  }
};

/**
 * The order the snake draft is called in.
 *
 * Fixed in advance by the commissioner — not derived from what anybody spent at
 * auction, and not drawn on the night by this app. It gets its own key for
 * exactly the reason team names do: `sameLeague` decides whether a draft in
 * progress survives a change, and reordering the snake must never throw one
 * away. It changes no price and no rule; it changes only who is next.
 *
 * Stored as team ids so a rename cannot disturb it. Missing or unknown ids are
 * repaired against the current teams rather than trusted, because a stored
 * order that has lost a team would silently drop that team from the draft.
 */
const SNAKE_ORDER_KEY = 'draft-vault:snake-order:v1';

const readStoredSnakeOrder = (): string[] => {
  try {
    const raw = localStorage.getItem(SNAKE_ORDER_KEY);
    const parsed = raw ? (JSON.parse(raw) as unknown) : null;
    if (!Array.isArray(parsed)) return [];
    return parsed.filter((id): id is string => typeof id === 'string');
  } catch {
    return [];
  }
};

const writeStoredSnakeOrder = (ids: readonly string[]): void => {
  try {
    if (!ids.length) localStorage.removeItem(SNAKE_ORDER_KEY);
    else localStorage.setItem(SNAKE_ORDER_KEY, JSON.stringify(ids));
  } catch {
    /* storage unavailable — the order simply falls back to the team order */
  }
};

const EMPTY_ROSTER = (): RosterCounts => ({ QB: 0, RB: 0, WR: 0, TE: 0, K: 0, DST: 0 });

const rosterSize = (roster: RosterCounts): number =>
  Object.values(roster).reduce((total, count) => total + count, 0);

export class AuctionDraftService {
  private players: Player[] = [];
  private teams: Team[] = [];
  private draftedCount = 0;
  /** Pick order, so the last one can be taken back. */
  private history: DraftPick[] = [];
  /**
   * Picks taken back, newest last, so an undo can be undone.
   *
   * Undo was destructive and silent: two accidental presses of "u" lost two
   * picks with nothing on screen to say which, and re-entering them meant
   * remembering a price somebody called out five minutes ago. Any new pick
   * clears this, which is the same rule the cleared-draft stash lives by —
   * once the draft has moved on, the branch that was taken back is genuinely
   * history and putting a pick from it back would splice it into a draft it
   * was never part of.
   *
   * It is deliberately not persisted and deliberately not shared. The pick log
   * is the only shared fact; this is a private note about what this window's
   * owner just did, and a second window that never pressed undo should not be
   * offering to redo it.
   */
  private undone: DraftPick[] = [];
  /**
   * True only while a redo is being put back.
   *
   * A redo goes through the ordinary draft path — it must, because the engine
   * re-checks every pick it records — and that path clears the stack. Without
   * this flag, redoing the first of three undone picks would throw the other
   * two away.
   */
  private redoing = false;
  /** When the draft last left this browser, or null if it never has. */
  private mark: ExportMark | null = readStoredMark();
  /** The commissioner's snake order, by team id. Empty means the team order. */
  private snakeOrder: string[] = readStoredSnakeOrder();
  /**
   * The league being drafted. Every rule and every dollar value derives from
   * it, so changing it re-prices the board rather than merely relabelling it.
   */
  private league: LeagueShape = POOL_LEAGUE;
  /** Replacement points per position under the active league. */
  private replacement: Record<string, number> = {};
  /**
   * Slots the reserve has to hold a dollar back for.
   *
   * A bid is capped at the budget minus a dollar for each of these, so that a
   * team cannot spend itself into a lineup it is unable to finish filling.
   *
   * That rule only holds when every roster spot has to be *bought*. In a
   * partial auction it is wrong, and wrong in the expensive direction: this
   * league auctions a commissioner's sheet of the best 50-100 players and fills
   * every remaining spot by snake draft, for free, with no minimum number a
   * team has to buy. A manager may legally put the whole $200 on three players
   * and snake the other thirteen. Holding $8 back for slots the snake will fill
   * caps our own bids below what the rules allow, and — worse — makes the room
   * read as poorer than it is, so an opponent looks tapped out at $88 when they
   * can still go to $96. Every bid we walk away from on that basis is a player
   * we lose while holding money we were never required to hold.
   *
   * So the reserve exists exactly when the auction covers the whole roster.
   *
   * The full-auction figure stays capped at the roster size: a league that
   * fields more players than it may roster is refused by the settings panel,
   * but if one ever reached the engine the reserve would exceed every budget
   * and no bid could be legal.
   */
  private get reservedSlots(): number {
    if (this.league.auctionSheetSize !== null) return 0;
    return Math.min(this.league.rosterSize, startingSlots(this.league));
  }
  /** Imported rankings, by player id. Empty unless somebody has imported some. */
  /**
   * The bundled draft-market snapshot, read once and refused if malformed.
   *
   * Static because it is a property of the build rather than of a draft, and
   * validated because the file is generated: anything malformed means the
   * generator moved under the reader, and a board silently priced off half a
   * market is worse than one priced off none.
   */
  private static readonly market: MarketSnapshot | null = validateMarket(marketData);

  private static readonly adpByGsis: Map<string, number> = new Map(
    (AuctionDraftService.market?.entries ?? []).map((entry) => [entry.gsis, entry.adp])
  );

  /** Keyed by the synthetic id `buildAbsentee` mints, since they have no gsis. */
  private static readonly adpByAbsentee: Map<string, number> = new Map(
    (AuctionDraftService.market?.absent ?? []).map((row) => [
      `market:${row.name.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`,
      row.adp,
    ])
  );

  private overrides: Record<string, RankingOverride> = readStoredOverrides();
  /** The commissioner's sheet, if one has been imported. Empty ids means none. */
  private sheet: StoredSheet = readStoredSheet();
  /** Told after every change that reached storage, so other windows can follow. */
  private listeners = new Set<() => void>();
  /**
   * True while rebuilding from a change another window made.
   *
   * Replaying a saved draft writes to storage on every pick, so without this
   * the rebuild would announce itself back and the two windows would rebuild
   * each other in a loop.
   */
  private applyingRemote = false;
  /** Names people actually answer to, over the default "Team 3". */
  private teamNames: Record<string, string> = {};
  /** Which team belongs to the person running this. */
  private myTeamId: string | null = null;

  constructor(league: LeagueShape = readStoredLeague()) {
    this.league = normaliseLeague(league);
    const stored = readStoredTeams();
    this.teamNames = stored.names ?? {};
    this.myTeamId = stored.mine ?? null;
    this.initializePlayers();
    this.initializeTeams();
  }

  /**
   * The pool is generated, not typed by hand: scripts/build-player-pool.mjs
   * derives it from nflverse rosters and production, and every field below
   * traces back to a real observation or to the documented projection model.
   */
  private initializePlayers(): void {
    const entries = poolData.players as PoolEntry[];
    const mask = this.sheetMask(entries);

    // The pool ships values for the league it was built for. Rather than trust
    // them, re-derive from projected points — which are league-independent —
    // through the same module the builder used. At the default shape this
    // reproduces the stored numbers exactly (there is a test that says so),
    // and at any other shape it is the only way they could be right.
    const {
      replacement,
      priced,
      onSheet: bought,
    } = pricePool(
      entries.map((entry) => ({
        position: entry.position,
        points: entry.projection.points,
        receptions: entry.projection.receptions,
      })),
      this.league,
      mask ? { onSheet: mask } : {}
    );
    this.replacement = replacement;

    /*
     * Who the money bought is read back off the pricing, never worked out a
     * second time here — that is the whole reason pricePool returns the mask.
     *
     * The exception is a full auction, where there is no sheet to be off. The
     * mask is then simply the best 192 by surplus, and marking the rest
     * snake-only would state a fact about a format this league is not playing.
     */
    const wholeBoard = this.league.auctionSheetSize === null && !mask;

    this.players = entries.map((entry, index) =>
      this.buildPlayer(entry, priced[index], wholeBoard || bought[index], mask !== undefined)
    );

    /*
     * The players the room drafts that the pool has never heard of.
     *
     * Appended *after* pricing, and that ordering is the whole design. They
     * have no projection — no tape, no usage, no schedule join — so they are
     * never in the array `pricePool` and `replacementLevels` see. Letting a
     * player with no projected points into that arithmetic would drag his
     * position's replacement level down and change every price on the board on
     * the strength of a number nobody has. So they cost the board nothing and
     * are simply also on it.
     *
     * That leaves them at the dollar floor until the market board is applied,
     * which is honest rather than convenient: $1 is not a claim that Keenan
     * Allen is worth a dollar, it is where every player we cannot price sits.
     * `consensusOverrides` then slots him onto his position's curve at the rank
     * real drafts give him, which is the only opinion about him anybody has.
     */
    for (const absentee of AuctionDraftService.market?.absent ?? []) {
      this.players.push(this.buildAbsentee(absentee, wholeBoard));
    }

    // The instruments on the board draw against the position, not against the
    // sixty men on the sheet, and the readings they scale by — snap share,
    // points per game — are derived here rather than shipped in the pool. Once
    // is enough: none of them is a function of the league or of a price.
    primeNorms(this.players, this.league.rostered);
  }

  /**
   * A player the market drafts and the pool lacks, made nominable.
   *
   * The zeroes here are not measurements and must never be read as any. `Player`
   * requires numbers on every headline field, so widening a dozen of them to
   * null for fifteen players would be a large change to the type every panel
   * reads. Instead `marketOnly` is the flag that carries "we know nothing", and
   * the rule it buys is that no panel may print one of these numbers — the same
   * discipline `draftCost` follows by staying undefined on a snake pick, since
   * a zero in a sum is indistinguishable from a measurement.
   *
   * He is also outside every average the board computes, because he is outside
   * `pricePool` entirely: these values are only ever read back, never summed.
   */
  private buildAbsentee(absentee: MarketAbsentee, wholeBoard: boolean): Player {
    const id = `market:${absentee.name.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`;
    // The same override the pool's own players go through. Without it the
    // market board would price him and the board would keep showing the dollar
    // floor, which is the one number we know to be meaningless for him.
    const override = this.overrides[id];
    const value = override?.value ?? 1;
    // A commissioner's sheet can name him — he is a candidate the paste matches
    // against like any other — and `sheetMask` cannot see him because it runs
    // over pool entries, so his membership is read straight off the sheet.
    const onSheet = this.sheet.ids.length ? this.sheet.ids.includes(id) : wholeBoard;
    return {
      id,
      name: absentee.name,
      position: absentee.position as PlayerPosition,
      team: absentee.team,
      tier: 4,
      baseValue: value,
      estimatedValue: value,
      modelValue: 1,
      // Nothing to rank him by; he sorts behind everybody we can price.
      modelRank: MARKET_ONLY_RANK,
      customRanking: override,
      onSheet,
      sheetIsStated: this.sheet.ids.length > 0,
      projectedPoints: 0,
      /*
       * Sorts last, and that is the whole point of the number.
       *
       * `adp` is our own rank and the board's default sort reads it directly.
       * At 0 these fourteen sorted *first*, so the app opened on a wall of
       * cards with no projection, no rank and no price — the worst possible
       * first impression, and made of exactly the players we know least about.
       * A sentinel past the end of the pool puts them where our knowledge of
       * them belongs: behind everybody we can actually price.
       */
      adp: MARKET_ONLY_RANK,
      injuryRisk: 'MEDIUM',
      valueOverReplacement: 0,
      upside: 0,
      floor: 0,
      consistency: 0,
      byeWeek: 0,
      ageRisk: 'MEDIUM',
      competitionLevel: 'MINOR_COMPETITION',
      recentTrends: 'STABLE',
      isDrafted: false,
      /** The one thing known about him, and the reason he is here at all. */
      marketOnly: true,
      market: {
        consensusRank: null,
        positionRank: null,
        rawEcr: null,
        best: null,
        worst: null,
        spread: null,
        ownership: null,
        searchRank: null,
        depthChartOrder: null,
        source: AuctionDraftService.market?.source ?? 'draft market',
        asOf: AuctionDraftService.market?.to ?? null,
        edge: null,
      },
    } as Player;
  }

  /**
   * The stored sheet as a mask over the pool, parallel to `entries`.
   *
   * Undefined when there is no sheet, which is what leaves `pricePool` to fall
   * back to `auctionSheetSize`. A sheet naming nobody in the pool — a file kept
   * across a pool rebuild — is also undefined rather than an auction of no
   * players, which would price all 628 at a dollar and lose the board.
   */
  /**
   * Whether this player is one the money is chasing.
   *
   * Five places asked `estimatedValue > 1` and meant this. The proxy holds only
   * while nothing overrides a price — and importing custom rankings, a shipped
   * feature, sets a value on whoever the importer ranked, including players the
   * commissioner left off the sheet. Those snake-only players then re-enter the
   * inflation denominator, so the room is told prices are softer than they are
   * for the rest of the night, and the bargain board starts recommending players
   * nobody is auctioning.
   *
   * The mask `pricePool` returned is the one answer. Nothing derives it again.
   */
  private forSale(player: Player): boolean {
    if (!player.onSheet) return false;
    // With a sheet in force the mask *is* the answer, and the price clause has
    // to go: a commissioner's list legitimately holds players we price at a
    // dollar — that is the whole reason a list is not a size — and ANDing the
    // proxy back on dropped five of the owner's real sixty out of everything
    // that counts what is for sale. The panel read "still for sale 47/55" over
    // a sixty-name sheet, par was computed over 55 and so came out high, and
    // `adviseOnNomination` could never put any of those five on the block.
    //
    // Without one, `onSheet` is everybody — `pricePool` has no list to mask
    // with — so whether the money is chasing him has to be inferred, and the
    // dollar floor is the only signal there is. That is the case the proxy was
    // written for and the only one it is right for.
    if (this.league.auctionSheetSize != null) return true;
    return player.estimatedValue > 1;
  }

  private sheetMask(entries: PoolEntry[]): boolean[] | undefined {
    if (!this.sheet.ids.length) return undefined;
    const wanted = new Set(this.sheet.ids);
    // Anybody already sold was, by definition, bought with money, so he belongs
    // on the sheet whatever the pasted list says. Sheets arrive late and arrive
    // incomplete — pasted after bidding has started, or with a row that came
    // back ambiguous — and without this a player sold for $55 is re-priced at $1
    // the moment the list lands. His grade becomes a D, and every drafted player
    // is summed at his post-import dollar, so the room is told it is paying a
    // 29% premium on evidence that is entirely an artefact of the import.
    // Bought with money, not merely off the board. A snake pick costs nothing,
    // so counting it here put free picks onto the sheet — and since the mask
    // decides what inflation and scarcity are measured over, a rebuild then
    // produced a board that replaying the identical log does not reproduce.
    const sold = new Set(
      this.players
        .filter((player) => player.isDrafted && player.draftCost != null)
        .map((player) => player.id)
    );
    const mask = entries.map((entry) => wanted.has(entry.gsis) || sold.has(entry.gsis));
    return mask.some(Boolean) ? mask : undefined;
  }

  /**
   * One pool entry, priced for this league and then overlaid with any imported
   * ranking. The model's number stays on `modelValue` either way, so nothing
   * downstream has to choose between showing ours and showing theirs.
   */
  private buildPlayer(
    entry: PoolEntry,
    priced: { vorp: number; auctionValue: number },
    onSheet: boolean,
    sheetIsStated: boolean
  ): Player {
    const override = this.overrides[entry.gsis];
    const value = override?.value ?? priced.auctionValue;

    return {
      id: entry.gsis,
      name: entry.name,
      position: entry.position as PlayerPosition,
      team: entry.team,
      tier: (override?.tier ?? entry.tier) as 1 | 2 | 3 | 4,
      // Both follow the import: an opinion nobody's advice reflects is decoration.
      baseValue: value,
      estimatedValue: value,
      modelValue: priced.auctionValue,
      modelRank: entry.rank,
      customRanking: override,
      // What this league awards, not the full-PPR total the pool ships.
      projectedPoints: Math.round(
        pointsFor(
          {
            position: entry.position,
            points: entry.projection.points,
            receptions: entry.projection.receptions,
          },
          this.league
        )
      ),
      // Rank by our own valuation. It is not an average draft position and is
      // not labelled as one.
      adp: override?.rank ?? entry.rank,
      injuryRisk: entry.injuryRisk,
      valueOverReplacement: Math.round(priced.vorp),
      upside: entry.ceiling,
      floor: entry.floor,
      consistency: entry.consistency,
      byeWeek: entry.byeWeek ?? 0,
      ageRisk: entry.ageRisk,
      age: entry.age ?? undefined,
      experience: entry.experience ?? undefined,
      lastSeasonGames: entry.lastSeasonGames ?? undefined,
      competitionLevel: entry.role,
      snapPercentage: entry.snapShare ?? undefined,
      targetShare: entry.targetShare ?? undefined,
      recentTrends: entry.trend === 'UNPROVEN' ? 'STABLE' : entry.trend,
      percentiles: entry.percentiles,
      pointsPerGame:
        entry.projection.expectedGames > 0
          ? Math.round(
              (pointsFor(
                {
                  position: entry.position,
                  points: entry.projection.points,
                  receptions: entry.projection.receptions,
                },
                this.league
              ) /
                entry.projection.expectedGames) *
                10
            ) / 10
          : entry.projection.pointsPerGame,
      expectedGames: entry.projection.expectedGames,
      gamesObserved: entry.projection.gamesObserved,
      usage: entry.usage ?? null,
      teamContext: entry.context ?? null,
      durability: entry.durability,
      competition: entry.competition,
      market: entry.market,
      breakoutSeason: entry.breakoutSeason ?? null,
      draftCapital: entry.draft ?? null,
      defense: entry.defense,
      onSheet,
      sheetIsStated,
      isDrafted: false,
    };
  }

  private initializeTeams(): void {
    this.teams = Array.from({ length: this.league.teams }, (_, i) => ({
      id: `team-${i + 1}`,
      name: this.teamNames[`team-${i + 1}`] || `Team ${i + 1}`,
      budget: this.league.budget,
      spent: 0,
      remaining: this.league.budget,
      roster: EMPTY_ROSTER(),
      projectedTotal: 0,
      strengthScore: 0,
      riskScore: 0,
      depthScore: 0,
      injuryInsurance: 0,
    }));
  }

  /** A fresh array each call: callers compare references to detect changes. */
  getPlayers(): Player[] {
    return [...this.players];
  }

  getTeams(): Team[] {
    return [...this.teams];
  }

  getDraftState(): DraftState {
    return {
      players: [...this.players],
      teams: [...this.teams],
      draftedCount: this.draftedCount,
      totalPlayers: this.players.length,
      currentPick: this.draftedCount + 1,
    };
  }

  /**
   * Whether this bid is legal, and if not, why.
   *
   * Callers should run this before offering a bid so the reason can be shown;
   * draftPlayer enforces it again regardless.
   */
  validateBid(playerId: string, teamId: string, cost: number): BidCheck {
    const player = this.players.find((p) => p.id === playerId);
    if (!player)
      return { ok: false, code: 'unknown-player', message: 'That player is not in the pool.' };
    if (player.isDrafted) return this.alreadyGone(player);

    const team = this.teams.find((t) => t.id === teamId);
    if (!team) return { ok: false, code: 'unknown-team', message: 'Pick a team first.' };

    return this.checkBid(player, team, cost);
  }

  /**
   * Everything about a bid that is a question of money and roster room.
   *
   * Split out of `validateBid` for the same reason `checkRoster` was split out
   * of this: a second caller needs it against a state that is not the live
   * board. `previewCorrection` has to answer what an amended pick log *would*
   * do before any of it is applied, and it does that by walking shadow teams —
   * the same rules, one set of them, applied to a state that has not happened
   * yet. A second copy of the arithmetic would be a second answer to "can this
   * team afford him", and the two would disagree on the only night it matters.
   *
   * Whether the player is already taken is not here: that is a fact about the
   * board, and the shadow walk has its own answer to it.
   */
  private checkBid(player: Player, team: Team, cost: number): BidCheck {
    // NaN fails every comparison, so it has to be rejected explicitly or it
    // sails through the budget check and turns the team's money into NaN.
    if (!Number.isInteger(cost) || cost < 1) {
      return {
        ok: false,
        code: 'invalid-amount',
        message: 'A bid must be a whole dollar amount of $1 or more.',
      };
    }

    const room = this.checkRoster(player, team);
    if (!room.ok) return room;

    const { spendable, held } = this.spendableFor(team);
    if (cost > spendable) {
      return {
        ok: false,
        code: 'insufficient-funds',
        message:
          held > 0
            ? `${team.name} can spend $${Math.max(0, spendable)} — $${held} is held back for ${held} open starting spot${held === 1 ? '' : 's'}.`
            : `${team.name} only has $${team.remaining} left.`,
      };
    }

    return { ok: true };
  }

  /**
   * Whether this team has room for this player at all, money aside.
   *
   * Split out of validateBid because a pick that costs nothing still has to
   * pass it, and because the most-they-can-bid question needs the money half
   * on its own. Two callers reading one copy is the point: a roster rule that
   * rejects a bid but not an identically illegal free pick is a rule in name
   * only.
   */
  /**
   * He is already somebody's, said once for both halves.
   *
   * The price is only mentioned when there was one. A snake pick has no
   * `draftCost`, and the auction's message interpolated it unconditionally —
   * which printed "already went to Team 4 for $undefined" the moment anybody
   * tried to nominate a player the snake had taken.
   */
  private alreadyGone(player: Player): BidRejection {
    const owner = this.teams.find((t) => t.id === player.draftedBy);
    const to = owner?.name ?? 'another team';
    return {
      ok: false,
      code: 'already-drafted',
      message:
        player.draftCost != null
          ? `${player.name} already went to ${to} for $${player.draftCost}.`
          : `${player.name} already went to ${to} in the snake.`,
    };
  }

  private checkRoster(player: Player, team: Team): BidCheck {
    if (rosterSize(team.roster) >= this.league.rosterSize) {
      return {
        ok: false,
        code: 'roster-full',
        message: `${team.name} already has ${this.league.rosterSize} players.`,
      };
    }
    if (team.roster[player.position] >= this.league.positionLimits[player.position]) {
      return {
        ok: false,
        code: 'position-full',
        message: `${team.name} cannot carry more than ${this.league.positionLimits[player.position]} at ${player.position}.`,
      };
    }
    return { ok: true };
  }

  /**
   * The most this team may legally commit to one player, and what is withheld.
   *
   * The reserve is `reservedSlots` — zero whenever the snake fills the rest of
   * the roster for free. Anything that wants to state a team's ceiling has to
   * come through here rather than recomputing it, or the number shown beside a
   * bid box drifts from the number the engine will actually accept, and the
   * first anyone knows of it is a rejected bid at the worst moment.
   */
  private spendableFor(team: Team): { spendable: number; held: number } {
    const held = Math.max(0, this.reservedSlots - rosterSize(team.roster) - 1);
    return { spendable: team.remaining - held, held };
  }

  draftPlayer(playerId: string, teamId: string, cost: number): boolean {
    if (!this.validateBid(playerId, teamId, cost).ok) return false;

    const player = this.players.find((p) => p.id === playerId)!;
    const team = this.teams.find((t) => t.id === teamId)!;

    player.isDrafted = true;
    player.draftedBy = teamId;
    player.draftCost = cost;
    player.pickNumber = this.draftedCount + 1;

    team.spent += cost;
    team.remaining -= cost;
    team.roster[player.position]++;
    team.projectedTotal += player.projectedPoints;

    this.draftedCount++;
    this.history.push({ playerId, teamId, cost, phase: 'auction' });
    this.dropRedo();
    this.updateTeamMetrics(team);
    this.persist();

    return true;
  }

  /**
   * Take a player in the snake, for nothing.
   *
   * Re-checks the rules exactly as `draftPlayer` re-checks `validateBid`: a
   * caller that skipped the check must not be able to put an illegal pick in
   * the log, because the log is the only shared fact and it replays on reload.
   *
   * No money moves and `draftCost` stays undefined — never 0. A snake pick is
   * not a player bought for nothing; he is a player nobody paid for, and every
   * premium, surplus and inflation reading downstream depends on being able to
   * tell the difference.
   */
  draftSnakePick(playerId: string, teamId: string): boolean {
    if (!this.validateSnakePick(playerId, teamId).ok) return false;
    return this.applySnakePick(playerId, teamId, this.getSnakeOnTheClock()?.slot);
  }

  /**
   * Put a snake pick on the board without asking whether it may be made.
   *
   * This is the half that replaying a saved log needs, and separating it is not
   * a convenience — it is the fix for a bug that destroyed drafts. `replay` used
   * to send every stored snake pick back through `validateSnakePick`, which
   * asks whether the team is on the clock *under the order in force now*. The
   * order lives outside the pick log, so reordering the board — the one thing
   * the order panel exists to do, and which it promises changes nothing already
   * taken — made every logged snake pick fail on the next reload. The second
   * window then wrote the truncated log back over the good one, and the picks
   * were gone. Importing a sheet mid-snake did the same thing by flipping the
   * phase back to auction.
   *
   * The principle it violated is worth stating plainly: a logged pick is a
   * record of what happened, not a proposal to be re-adjudicated against
   * today's rules. What replay still checks is what cannot have been true —
   * that the player exists, is not already taken, and fits the roster.
   * Whose turn it was belongs on the live path, where a person is about to act.
   */
  private applySnakePick(playerId: string, teamId: string, slot?: number): boolean {
    const player = this.players.find((p) => p.id === playerId);
    const team = this.teams.find((t) => t.id === teamId);
    if (!player || !team || player.isDrafted) return false;
    if (!this.checkRoster(player, team).ok) return false;

    player.isDrafted = true;
    player.draftedBy = teamId;
    player.pickNumber = this.draftedCount + 1;

    team.roster[player.position]++;
    team.projectedTotal += player.projectedPoints;

    this.draftedCount++;
    // A log written before the seat was recorded still replays; it simply
    // resumes the board from wherever the walk had reached.
    this.history.push({
      playerId,
      teamId,
      phase: 'snake',
      slot: slot ?? this.getSnakeUpcoming(1)[0]?.slot,
    });
    this.dropRedo();
    this.updateTeamMetrics(team);
    this.persist();

    return true;
  }

  /**
   * Takes back the most recent pick. Returns the undone pick, or null.
   *
   * `cost` is null for a snake pick, for the same reason `draftCost` is absent
   * on one: there was no price, and zero would be a claim about one.
   */
  undoLastPick(): { player: Player; team: Team; cost: number | null } | null {
    const last = this.history.pop();
    if (!last) return null;

    const player = this.players.find((p) => p.id === last.playerId);
    const team = this.teams.find((t) => t.id === last.teamId);
    if (!player || !team) return null;

    player.isDrafted = false;
    delete player.draftedBy;
    delete player.draftCost;
    delete player.pickNumber;

    // A snake pick moved no money, so there is none to give back. Undoing one
    // also puts the room back in the auction, which needs no code here: the
    // phase is derived from the log, and the log is one entry shorter.
    const cost = last.phase === 'snake' ? null : (last.cost ?? 0);
    team.spent -= cost ?? 0;
    team.remaining += cost ?? 0;
    team.roster[player.position] = Math.max(0, team.roster[player.position] - 1);
    team.projectedTotal -= player.projectedPoints;

    this.draftedCount = Math.max(0, this.draftedCount - 1);
    // Kept, so it can be put back. Pressing "u" twice by accident used to lose
    // two picks outright, and the room's only remedy was remembering what they
    // were. Recorded after the undo has actually succeeded: an entry naming a
    // player or a team the pool no longer has cannot be replayed, so offering
    // to redo it would be an offer that fails when it is taken up.
    this.undone.push(last);
    this.updateTeamMetrics(team);
    this.persist();

    return { player, team, cost };
  }

  /**
   * Put back the pick the last undo took away.
   *
   * It goes back through the ordinary draft path rather than being pushed
   * straight onto the log, because the engine re-checks everything it records
   * and a redo is no exception: in the time since the undo, a second window may
   * have bought the player, an import may have changed the roster rules, or a
   * correction may have rebuilt the draft around him. If the pick can no longer
   * be made it is dropped rather than kept, since an offer that fails every
   * time it is taken up is worse than no offer at all.
   *
   * `cost` is null for a snake pick, exactly as `undoLastPick` reports it.
   */
  redoLastUndo(): RedoOutcome | null {
    const next = this.undone.pop();
    if (!next) return null;

    this.redoing = true;
    let done = false;
    try {
      done =
        next.phase === 'snake'
          ? this.applySnakePick(next.playerId, next.teamId, next.slot)
          : this.draftPlayer(next.playerId, next.teamId, next.cost ?? 0);
    } finally {
      this.redoing = false;
    }
    const player = this.players.find((p) => p.id === next.playerId);
    const team = this.teams.find((t) => t.id === next.teamId);

    // A refusal has to be reported, not swallowed. The entry has already been
    // popped, so returning a bare null discarded the only remaining copy of
    // that pick while the room showed nothing at all: the owner pressed "r",
    // saw no change, and the pick was gone.
    if (!done || !player || !team) {
      const why = player && team ? this.checkBid(player, team, next.cost ?? 0) : null;
      return {
        ok: false,
        reason:
          why && !why.ok
            ? why.message
            : 'That pick can no longer be made — the board has moved on from it.',
      };
    }

    return {
      ok: true,
      player,
      team,
      cost: next.phase === 'snake' ? null : (next.cost ?? 0),
    };
  }

  /** Whether there is an undone pick waiting to be put back. */
  canRedo(): boolean {
    return this.undone.length > 0;
  }

  /** How many picks are waiting to be put back. */
  undoneCount(): number {
    return this.undone.length;
  }

  /**
   * Forget the undone picks.
   *
   * Called wherever the draft moves on — a new pick, a correction, a reset, a
   * file — because from there the undone branch describes a draft that no
   * longer exists. The redo itself is the one caller that must not trigger it,
   * which is what `redoing` is for.
   */
  private dropRedo(): void {
    if (!this.redoing) this.undone = [];
  }

  // -------------------------------------------------------------------------
  // correcting the record
  //
  // One person keeps this record while eleven others draft on paper, and in a
  // live auction a price is misheard and a team is written down wrong. Undo
  // could only ever pop the end of the log, so noticing at pick sixty that pick
  // forty was wrong meant throwing away twenty good picks and re-entering them
  // from memory — which is how a small error becomes a lost afternoon.
  //
  // A correction amends one entry and then replays the amended log through the
  // same `replay` every other door uses. Nothing here re-implements a rule: the
  // draft that comes out is the draft those picks would have built if they had
  // been recorded correctly in the first place.
  // -------------------------------------------------------------------------

  /**
   * What correcting this pick would do, before any of it is done.
   *
   * A correction can legitimately make a later pick illegal — a raised price
   * that busts a budget, a player who now appears twice — and those picks are
   * lost when the amended log is replayed. That has to be a question the room
   * is asked rather than something it discovers afterwards, so this answers it
   * against shadow teams and changes nothing.
   */
  previewCorrection(index: number, change: PickCorrection): CorrectionCheck {
    const planned = this.planCorrection(index, change);
    if (!planned.ok) return planned;

    const { picks, failures, restored } = planned;

    // The amendment failing on its own pick is a refusal, not collateral. It
    // was landing in `invalidated` beside genuinely later picks, so the panel
    // headed it "1 later pick could no longer have happened" — naming the pick
    // being edited, which is not a later pick — and left Apply enabled reading
    // "Apply, losing 1", on a correction `correctPick` always refuses. A
    // destructive-looking button that cannot act, on the one screen whose job
    // is to say exactly what an action will cost.
    const own = failures.find((failure) => failure.index === index);
    if (own) return { ok: false, reason: own.rejection.message };

    return {
      ok: true,
      restored,
      skipped: picks.length - restored,
      invalidated: failures.map((failure) => ({
        // Where the pick sits in the log as the board shows it now. Replaying
        // will renumber whatever survives, but the room is being asked about
        // the picks it can see, and those are the ones it can see.
        pickNumber: failure.index + 1,
        player: this.players.find((p) => p.id === picks[failure.index].playerId)?.name ?? 'Unknown',
        team: this.teams.find((t) => t.id === picks[failure.index].teamId)?.name ?? 'Unknown',
        reason: failure.rejection.message,
      })),
    };
  }

  /**
   * Amend one pick and rebuild the draft from the amended log.
   *
   * The phase travels with the entry untouched, and correcting a pick can
   * legitimately move where the auction ended: swapping the sale that emptied
   * the sheet for a player who was never on it leaves a sheet player still to
   * sell, so `getPhase` reads `auction` again. The snake picks that follow keep
   * the phase they were taken in and replay exactly as they were, because
   * `applySnakePick` re-checks what cannot have been true — the player, the
   * roster — and not whose turn it was. A logged pick is a record of what
   * happened, not a proposal to be re-adjudicated against a sheet that has
   * since changed shape.
   *
   * Reports what replayed and what did not, exactly as `importDraft` does.
   */
  correctPick(index: number, change: PickCorrection): CorrectionResult {
    const planned = this.planCorrection(index, change);
    if (!planned.ok) return planned;

    // A correction that cannot keep the pick it is correcting would delete it,
    // which is the opposite of what anybody pressing Apply is asking for. It is
    // refused in the engine's own words rather than applied and counted.
    const own = planned.failures.find((failure) => failure.index === index);
    if (own) return { ok: false, reason: own.rejection.message };

    return this.rebuild(planned.picks);
  }

  /**
   * The amended log, and what replaying it would cost — without applying it.
   *
   * Everything either public entry point needs, worked out once, so a preview
   * and the correction it previews cannot come to different answers.
   */
  private planCorrection(
    index: number,
    change: PickCorrection
  ):
    | { ok: false; reason: string }
    | {
        ok: true;
        picks: DraftPick[];
        restored: number;
        failures: Array<{ index: number; rejection: BidRejection }>;
      } {
    if (!Number.isInteger(index) || index < 0 || index >= this.history.length) {
      return { ok: false, reason: 'There is no pick at that place in the draft.' };
    }

    const amended: DraftPick = { ...this.history[index] };

    if (change.playerId !== undefined) {
      if (!this.players.some((player) => player.id === change.playerId)) {
        return { ok: false, reason: 'That player is not in the pool.' };
      }
      amended.playerId = change.playerId;
    }

    if (change.teamId !== undefined) {
      if (!this.teams.some((team) => team.id === change.teamId)) {
        return { ok: false, reason: 'That team is not in this league.' };
      }
      amended.teamId = change.teamId;
    }

    if (change.cost !== undefined) {
      // A snake pick carries no price and must not gain one. Zero is not the
      // safe answer either: it reads as "bought for nothing", which is a claim
      // about money, and the premium, surplus and inflation readings cannot
      // tell it back out again from a free pick once it is in a sum.
      if (amended.phase === 'snake') {
        return {
          ok: false,
          reason: 'A snake pick has no price to correct — nobody paid for him.',
        };
      }
      if (!Number.isInteger(change.cost) || change.cost < 1) {
        return { ok: false, reason: 'A bid must be a whole dollar amount of $1 or more.' };
      }
      amended.cost = change.cost;
    }

    const picks = [...this.history];
    picks[index] = amended;

    const { restored, failures } = this.wouldReplay(picks);
    return { ok: true, picks, restored, failures };
  }

  /**
   * Replay a pick log against shadow teams, and say what would not land.
   *
   * The point of the shadows is that the rules stay in one place: this walks
   * `checkBid` and `checkRoster` — the same two calls the live path makes —
   * over teams that start empty and fill as the log is read, so the answer it
   * gives is the answer the board will give when the log is actually replayed.
   * A test bids one against the other, because a warning that disagrees with
   * what then happens is worse than no warning.
   */
  private wouldReplay(picks: ReadonlyArray<DraftPick>): {
    restored: number;
    failures: Array<{ index: number; rejection: BidRejection }>;
  } {
    const shadows = new Map(
      this.teams.map((team) => [
        team.id,
        { ...team, spent: 0, remaining: team.budget, roster: EMPTY_ROSTER() },
      ])
    );
    const taken = new Set<string>();
    const failures: Array<{ index: number; rejection: BidRejection }> = [];
    let restored = 0;

    picks.forEach((pick, index) => {
      const fail = (rejection: BidRejection) => failures.push({ index, rejection });

      const player = this.players.find((p) => p.id === pick.playerId);
      if (!player) {
        fail({ ok: false, code: 'unknown-player', message: 'That player is not in the pool.' });
        return;
      }
      if (taken.has(player.id)) {
        fail({
          ok: false,
          code: 'already-drafted',
          message: `${player.name} is taken earlier in the draft.`,
        });
        return;
      }
      const team = shadows.get(pick.teamId);
      if (!team) {
        fail({ ok: false, code: 'unknown-team', message: 'That team is not in this league.' });
        return;
      }

      // A snake pick is free, so only the roster can refuse it — the same half
      // of the rules `applySnakePick` re-checks on the live path.
      const check =
        pick.phase === 'snake'
          ? this.checkRoster(player, team)
          : this.checkBid(player, team, pick.cost ?? 0);
      if (!check.ok) {
        fail(check);
        return;
      }

      taken.add(player.id);
      team.roster[player.position]++;
      if (pick.phase !== 'snake') {
        const cost = pick.cost ?? 0;
        team.spent += cost;
        team.remaining -= cost;
      }
      restored++;
    });

    return { restored, failures };
  }

  /**
   * Throw the board away and build it again from a pick log.
   *
   * The same three steps `importDraft` takes, for the same reason: every
   * derived number — a roster, a budget, a price, whose turn it is — comes back
   * from replaying the log, so a corrected draft cannot end up as the old draft
   * with one entry painted over.
   *
   * Budgets are carried across by hand because they are not in the log and not
   * in the league: a team whose budget was adjusted keeps it, exactly as a file
   * carries budgets beside the picks.
   */
  private rebuild(picks: ReadonlyArray<DraftPick>): CorrectionResult {
    const budgets = this.teams.map((team) => ({ id: team.id, budget: team.budget }));

    // Stash the log as it stands, into the same place a reset stashes it.
    //
    // A correction that drops later picks is the more dangerous of the two
    // destructive acts, not the lesser: a reset is all-or-nothing and obvious,
    // while this deletes an arbitrary tail behind a button that reads "Apply,
    // losing 34". Reset earned its undo net by destroying an afternoon; there
    // is no argument for the sharper instrument having none.
    if (this.history.length) {
      try {
        localStorage.setItem(
          CLEARED_STORAGE_KEY,
          JSON.stringify({
            clearedAt: new Date().toISOString(),
            league: this.league,
            budgets,
            picks: this.history,
          })
        );
      } catch {
        /* storage unavailable — the correction is simply not undoable */
      }
    }

    this.draftedCount = 0;
    this.history = [];
    // The undone branch belonged to the log that has just been replaced.
    this.undone = [];
    this.initializePlayers();
    this.initializeTeams();
    for (const { id, budget } of budgets) this.updateTeamBudget(id, budget);

    const restored = this.replay(picks);
    this.persist();
    return { ok: true, restored, skipped: picks.length - restored };
  }

  /**
   * Whose turn it is to nominate.
   *
   * Derived from the number of picks made rather than stored, so it can never
   * drift out of step with the draft and needs nothing extra synchronised if
   * this ever runs on more than one screen.
   */
  /**
   * Whether this team can still add anybody.
   *
   * A full roster is the practical end of a team's draft: the reserve rules
   * guarantee it can always afford a dollar for each open slot, so money never
   * strands a team with room.
   */
  canDraft(team: Team): boolean {
    return rosterSize(team.roster) < this.league.rosterSize;
  }

  /** True once no team has room for another player. */
  isComplete(): boolean {
    return this.teams.length > 0 && this.teams.every((team) => !this.canDraft(team));
  }

  /**
   * Whose turn it is to nominate.
   *
   * Rotation is still derived from the pick count rather than stored, but it
   * steps over teams that are full — a team whose roster is finished does not
   * keep getting handed the nomination, and at the end of the draft nobody is.
   */
  getNominatingTeam(): Team | undefined {
    if (!this.teams.length) return undefined;
    const start = this.draftedCount % this.teams.length;
    for (let step = 0; step < this.teams.length; step++) {
      const team = this.teams[(start + step) % this.teams.length];
      if (this.canDraft(team)) return team;
    }
    return undefined;
  }

  /** Nomination order from here, starting with whoever is up. */
  getNominationOrder(count = 4): Team[] {
    return Array.from(
      { length: Math.min(count, this.teams.length) },
      (_, offset) => this.teams[(this.draftedCount + offset) % this.teams.length]
    );
  }

  // -------------------------------------------------------------------------
  // the snake half
  //
  // The auction buys the commissioner's sheet; every remaining roster spot is
  // filled by a serpentine draft in an order he fixes in advance. Which half
  // the room is in is derived from the log and the sheet, never stored as
  // current state — so reloading, following a second window, replaying a file
  // and undoing all land on the same answer, because they all replay the same
  // log.
  // -------------------------------------------------------------------------

  /**
   * Which half of the draft the room is in.
   *
   * The auction is over when every player on the sheet is either sold or marked
   * as passed over, which is exactly what `getSheetRemaining` answers. With no
   * sheet in force there is no snake phase at all: the app does not know which
   * players the money was buying, so it cannot know when the money is finished,
   * and claiming otherwise mid-auction would take the bid box off the screen
   * with names still to call.
   */
  getPhase(): DraftPhase {
    if (!this.sheet.ids.length) return 'auction';
    return this.getSheetRemaining().length === 0 ? 'snake' : 'auction';
  }

  /**
   * The snake order in force: the commissioner's, or the team order.
   *
   * Repaired against the current teams on every read rather than trusted, so a
   * stored order written under a different league — or one that lost a team to
   * a hand-edited storage key — cannot drop a team out of the draft entirely.
   */
  /**
   * Whether the order has actually been *drawn*, as opposed to stood in for.
   *
   * `getSnakeOrder` repairs itself against the current teams and backfills
   * everybody missing, which is right for running the snake — somebody has to
   * be on the clock, and an order that lost a team must not drop that team out
   * of the draft. It is wrong for answering "where do I pick", and the two were
   * the same call.
   *
   * The cost of that was not a missing feature but a confident wrong number.
   * `getSpendOutlook` guarded itself with `!getSnakeOrder().length`, which can
   * never be true while there are teams, so the guard was dead and the outlook
   * was computed at the *team* order — first in the list picks first. The owner
   * is team one by default, so the panel printed "at your pick 1" and "free at
   * your pick: Jalen Hurts · 312 pts" for a draw nobody had made, on the one
   * number this format turns on. At quarterback the true figure runs from a
   * gain of 48 at the first seat to 136 at the last, so the most favourable
   * possible draw was being reported as the fact, and the advice that follows
   * from it — do not buy a quarterback — is the opposite of the advice a late
   * draw calls for.
   *
   * So: drawn or not is its own question, and the outlook falls through to the
   * bound across every seat until it has been answered.
   */
  hasSnakeOrder(): boolean {
    return this.snakeOrder.length > 0;
  }

  getSnakeOrder(): Team[] {
    const byId = new Map(this.teams.map((team) => [team.id, team]));
    const ordered: Team[] = [];
    for (const id of this.snakeOrder) {
      const team = byId.get(id);
      if (team && !ordered.includes(team)) ordered.push(team);
    }
    for (const team of this.teams) if (!ordered.includes(team)) ordered.push(team);
    return ordered;
  }

  /**
   * Set the order the snake is called in.
   *
   * Allowed mid-draft on purpose: the order is announced at the table, and it
   * is announced differently often enough that refusing to change it would mean
   * running the rest of the night off a list everyone can see is wrong. It
   * moves nobody's money and invalidates no pick already made — only who is
   * next — which is why it is not a league change and does not clear the draft.
   */
  setSnakeOrder(teamIds: readonly string[]): void {
    const known = new Set(this.teams.map((team) => team.id));
    this.snakeOrder = [...new Set(teamIds)].filter((id) => known.has(id));
    writeStoredSnakeOrder(this.snakeOrder);
    this.announce();
  }

  /** How many picks the snake has taken so far. */
  getSnakePickCount(): number {
    return this.history.reduce((total, pick) => total + (pick.phase === 'snake' ? 1 : 0), 0);
  }

  /**
   * Who is on the clock in the snake, and where in the board they are.
   *
   * Serpentine over the fixed order — round one forward, round two reversed —
   * computed from the number of snake picks made rather than stored, exactly as
   * `getNominatingTeam` is computed from the pick count. A team whose roster is
   * full is stepped over, because this format has no minimum a team must buy at
   * auction and so rosters fill at wildly different times.
   *
   * The walk starts from an empty snake and replays the whole schedule rather
   * than indexing straight into it. Indexing is what looks obvious and is
   * wrong: skipping a full team shifts every later slot, so slot number and
   * pick number stop agreeing, and the team after a full one gets handed two
   * picks in a row. Two hundred iterations of arithmetic is not worth being
   * clever about.
   */
  getSnakeOnTheClock(): SnakeSlot | undefined {
    return this.getSnakeUpcoming(1)[0];
  }

  /**
   * The next few snake slots, in order, starting with whoever is on the clock.
   *
   * The question a snake draft actually turns on is not who is picking now but
   * how long it is until you pick again — at the turn you take two in a row, in
   * the middle of a round you wait twenty-two. That is a fact about the order
   * and the rosters, so it is computed here rather than by whoever renders it.
   */
  getSnakeUpcoming(count = 4): SnakeSlot[] {
    const order = this.getSnakeOrder();
    if (!order.length || count < 1) return [];

    // Rosters as they stand, and the board resumed after the last seat somebody
    // actually took. Both halves of that matter. Rebuilding the rosters as the
    // snake found them and re-walking from seat zero meant every pick already
    // taken was re-attributed through the current order, so a reorder moved the
    // clock onto a team that was already full and wedged the draft with no way
    // forward from the room — every player rejected as roster-full and the
    // draft never complete.
    const filled = new Map(order.map((team) => [team.id, rosterSize(team.roster)]));
    let open = order.reduce(
      (total, team) => total + Math.max(0, this.league.rosterSize - (filled.get(team.id) ?? 0)),
      0
    );

    const made = this.getSnakePickCount();
    const taken = this.history.reduce(
      (last, pick) =>
        pick.phase === 'snake' && pick.slot != null ? Math.max(last, pick.slot) : last,
      -1
    );

    const upcoming: SnakeSlot[] = [];
    for (let slot = taken + 1; open > 0 && upcoming.length < count; slot++) {
      const team = this.seatAt(slot, order);
      if ((filled.get(team.id) ?? 0) >= this.league.rosterSize) continue;
      upcoming.push({
        team,
        round: Math.floor(slot / order.length) + 1,
        pick: (slot % order.length) + 1,
        overall: made + upcoming.length + 1,
        slot,
      });
      filled.set(team.id, (filled.get(team.id) ?? 0) + 1);
      open--;
    }
    return upcoming;
  }

  /**
   * Whose seat this is on the endless serpentine board.
   *
   * Even rounds run left to right and odd rounds run back again; that is the
   * whole of a serpentine order.
   */
  private seatAt(slot: number, order: Team[]): Team {
    const round = Math.floor(slot / order.length);
    const seat = slot % order.length;
    return order[round % 2 === 0 ? seat : order.length - 1 - seat];
  }

  /**
   * Whether this free pick is legal, and if not, why.
   *
   * The same typed answer a bid gets, because the room renders it the same way
   * and a rejection nobody can read is a rejection nobody can act on. It is
   * `checkRoster` — the half of `validateBid` that has nothing to do with
   * money, split out for exactly this — plus the two things only a snake pick
   * can get wrong: being taken while the auction is still running, and being
   * taken by a team that is not on the clock.
   */
  validateSnakePick(playerId: string, teamId: string): BidCheck {
    const player = this.players.find((p) => p.id === playerId);
    if (!player)
      return { ok: false, code: 'unknown-player', message: 'That player is not in the pool.' };
    if (player.isDrafted) return this.alreadyGone(player);

    const team = this.teams.find((t) => t.id === teamId);
    if (!team) return { ok: false, code: 'unknown-team', message: 'Pick a team first.' };

    if (this.getPhase() !== 'snake') {
      const left = this.getSheetRemaining().length;
      return {
        ok: false,
        code: 'not-in-snake',
        message: this.sheet.ids.length
          ? `The auction is still running — ${left} sheet player${left === 1 ? '' : 's'} left to sell or pass over.`
          : 'There is no snake phase without the commissioner’s sheet, so the room does not know when the auction ended.',
      };
    }

    const room = this.checkRoster(player, team);
    if (!room.ok) return room;

    const onTheClock = this.getSnakeOnTheClock();
    if (!onTheClock || onTheClock.team.id !== teamId) {
      return {
        ok: false,
        code: 'not-your-turn',
        message: onTheClock
          ? `It is ${onTheClock.team.name} on the clock, not ${team.name}.`
          : 'Every roster is full — there is nobody left to pick.',
      };
    }

    return { ok: true };
  }

  /**
   * How the room is behaving, as numbers a bidder can act on.
   *
   * Inflation above 1 means more money is chasing less value than the list
   * prices assume, so everything left will go for more than it says on the tin.
   * The premium is what has actually happened so far: what the room paid
   * divided by what we said those players were worth.
   */
  getMarketState(): MarketState {
    const drafted = this.players.filter((p) => p.isDrafted);
    /*
     * Money counts the auction; supply counts both halves.
     *
     * A receiver taken in the snake is genuinely off the board, so scarcity,
     * tier depletion and every "gone" count include him — waiting for him is no
     * longer an option and that is what those numbers are for. But nobody paid
     * for him, so he cannot appear in anything measuring what the room pays:
     * averaging a free player into the premium drags it toward zero and reports
     * a room paying 60% under list for the rest of the night, on a hundred and
     * forty picks in which no money changed hands at all.
     */
    const bought = drafted.filter((p) => p.draftCost != null);
    const spent = bought.reduce((total, p) => total + (p.draftCost ?? 0), 0);
    const listed = bought.reduce((total, p) => total + p.estimatedValue, 0);

    const positions: PlayerPosition[] = ['QB', 'RB', 'WR', 'TE', 'K', 'DST'];
    const scarcity = positions.map((position) => {
      const startable = this.players.filter((p) => p.position === position && this.forSale(p));
      const sold = bought.filter((p) => p.position === position);
      const soldFor = sold.reduce((total, p) => total + (p.draftCost ?? 0), 0);
      const soldList = sold.reduce((total, p) => total + p.estimatedValue, 0);

      // The drop from the best player left to the fifth-best: how much it costs
      // to wait. A big cliff is why a position becomes urgent.
      const remaining = startable
        .filter((p) => !p.isDrafted)
        .sort((a, b) => b.projectedPoints - a.projectedPoints);
      const cliff =
        remaining.length > 4
          ? Math.round(remaining[0].projectedPoints - remaining[4].projectedPoints)
          : 0;

      return {
        position,
        // Off the board, however he left it. A sheet player nobody bid on and
        // somebody then took in the snake is exactly as unavailable as one who
        // went for $40, and this is the number that says whether waiting is
        // still an option. `sold` below is the money question and counts only
        // the ones that were bought; the two genuinely differ once the snake
        // starts, and they are meant to.
        gone: startable.filter((p) => p.isDrafted).length,
        total: startable.length,
        tierOneLeft: this.players.filter(
          (p) => p.position === position && p.tier === 1 && !p.isDrafted
        ).length,
        /** What the room paid for this position against our list, once two have sold. */
        premium: sold.length >= 2 && soldList > 0 ? soldFor / soldList : null,
        sold: sold.length,
        cliff,
      };
    });

    return {
      inflation: this.calculateMarketInflation(),
      premium: listed > 0 ? spent / listed : null,
      moneyLeft: this.teams.reduce((total, team) => total + team.remaining, 0),
      valueLeft: this.players
        .filter((p) => !p.isDrafted && this.forSale(p))
        .reduce((total, p) => total + p.estimatedValue, 0),
      scarcity,
    };
  }

  // -------------------------------------------------------------------------
  // what the room can still do
  //
  // Three things a bidder cannot work out from the board: who is able to beat
  // the bid on the table, what a list price is actually worth tonight, and
  // which shelf is about to empty. All three are observations — they report
  // what the pick log and the rules already say — so they belong here.
  //
  // The matching opinions live in draftAdvisor and nowhere else: what a
  // rational opponent would *actually* pay, and which of these facts is worth
  // interrupting somebody for.
  // -------------------------------------------------------------------------

  /**
   * Every player the money is still chasing.
   *
   * The one public reading of the sheet mask, so nothing outside the engine
   * ever has to write `estimatedValue > 1` again. That proxy stood in for this
   * in five places and is wrong in exactly one case — an imported ranking
   * prices a snake-only player above a dollar — after which the advisor starts
   * recommending the room auction somebody nobody is auctioning.
   *
   * Includes players already sold: what is *for sale* and what is *left* are
   * different questions, and callers that want the second filter on
   * `isDrafted`, which they can see.
   */
  getForSale(): Player[] {
    return this.players.filter((player) => this.forSale(player));
  }

  /**
   * Where the inflation number came from, in the pieces that made it.
   *
   * `calculateMarketInflation` is this function's first field, so there is one
   * definition of the multiplier and one of its provenance. Splitting them
   * would let the panel explain a number the board is not using.
   */
  getInflationBasis(): InflationBasis {
    const forSale = this.players.filter((p) => this.forSale(p));
    const left = forSale.filter((p) => !p.isDrafted);
    const valueLeft = left.reduce((total, p) => total + p.estimatedValue, 0);
    const openSlots = this.teams.reduce(
      (total, team) =>
        total +
        Math.max(0, this.reservedSlots - Object.values(team.roster).reduce((a, b) => a + b, 0)),
      0
    );
    const moneyLeft = this.teams.reduce((total, team) => total + team.remaining, 0) - openSlots;

    /*
     * Nothing inflates once the money stops.
     *
     * In the snake, money left is fixed while value left goes on shrinking, so
     * the ratio climbs on its own until it pins at the ceiling and the market
     * panel reads "money is chasing scraps" for a hundred and forty picks in
     * which nobody spends a penny. Whatever is still in the room at the end of
     * the auction stays there.
     */
    const frozen = this.getPhase() === 'snake';
    const measurable = valueLeft > 0;
    const raw = measurable ? moneyLeft / valueLeft : 1;
    const inflation =
      frozen || !measurable
        ? 1
        : Math.max(INFLATION_BOUNDS.min, Math.min(INFLATION_BOUNDS.max, raw));

    return {
      inflation,
      moneyLeft,
      valueLeft,
      openSlots,
      raw,
      clamped:
        frozen || !measurable
          ? null
          : raw < INFLATION_BOUNDS.min
            ? 'floor'
            : raw > INFLATION_BOUNDS.max
              ? 'ceiling'
              : null,
      frozen,
      forSaleLeft: left.length,
      forSaleTotal: forSale.length,
    };
  }

  /**
   * What everything still on the board is worth at tonight's prices.
   *
   * Read the inflation and the for-sale mask once, then answer per player —
   * rather than a `getAdjustedValue(player)` that would recompute the phase and
   * re-filter six hundred players for each of sixty table rows.
   *
   * A player nobody is auctioning keeps his list price untouched. Inflating a
   * $1 snake player to $2 states that the money is chasing him, which is the
   * one thing the sheet says it is not doing.
   */
  getPriceAdjuster(): PriceAdjuster {
    const { inflation, frozen } = this.getInflationBasis();
    const forSale = new Set(this.players.filter((p) => this.forSale(p)).map((p) => p.id));
    return {
      inflation,
      frozen,
      price: (player: Player) =>
        forSale.has(player.id)
          ? inflatedPrice(player.estimatedValue, inflation)
          : player.estimatedValue,
    };
  }

  /**
   * Who can still take this player off you, and how far the rules let them go.
   *
   * Every ceiling comes from `spendableFor` — the same call `validateBid` makes
   * — because a ceiling shown beside the bid box that the engine would then
   * reject is the worst bug this feature could have. Teams with no room for him
   * are counted separately rather than listed at $0: they are not quiet
   * bidders, they cannot bid at all.
   *
   * Ordering is by ceiling, which is the only ordering a fact can claim.
   * Ranking opponents by how much of a threat they *are* takes a view about
   * what they want, and that is the advisor's job.
   */
  getBidCompetition(playerId: string, currentBid = 0): BidCompetition | null {
    const player = this.players.find((p) => p.id === playerId);
    if (!player || player.isDrafted) return null;

    // A bid has to be beaten, not matched, and the floor is the dollar every
    // player costs. A blank or half-typed bid box reads as nothing bid yet.
    const bid = Number.isFinite(currentBid) ? Math.max(0, Math.floor(currentBid)) : 0;
    const toBeat = Math.max(1, bid + (bid > 0 ? 1 : 0));

    const rivals: RivalBidder[] = [];
    let mine: RivalBidder | null = null;
    let blocked = 0;
    let outspent = 0;

    for (const team of this.teams) {
      const { spendable, held } = this.spendableFor(team);
      const row: RivalBidder = {
        team,
        ceiling: Math.max(0, spendable),
        held,
        need: unfilledSlotsFor(player.position, team.roster, this.league),
        have: team.roster[player.position] ?? 0,
        mine: team.id === this.myTeamId,
        canRoster: this.checkRoster(player, team).ok,
      };

      // The owner's own row is reported whatever it says, including that they
      // have no room. Testing the roster first and skipping meant `mine` came
      // back null for a team that was marked, so the panel asked the owner to
      // do something they had already done — and counted their own team in the
      // opponents who cannot bid.
      if (row.mine) {
        mine = row;
        continue;
      }
      if (!row.canRoster) blocked++;
      else if (row.ceiling >= toBeat) rivals.push(row);
      else outspent++;
    }

    rivals.sort((a, b) => b.ceiling - a.ceiling || a.team.name.localeCompare(b.team.name));
    return { currentBid: bid, rivals, mine, blocked, outspent };
  }

  /**
   * How fast each position has been leaving the board.
   *
   * Supply, so both halves count: a receiver taken in the snake is as gone as
   * one bought for $40. The window is the last few picks of the log whatever
   * phase they happened in.
   *
   * What is *left* is counted as players above replacement rather than players
   * for sale, and that difference matters once the snake starts: for-sale means
   * on the sheet, and in the snake nobody left is, so a for-sale count would
   * report every position as empty and every pick as a run.
   */
  getPositionRuns(window = 10): PositionRun[] {
    const recent = this.history.slice(-Math.max(1, window));
    const byId = new Map(this.players.map((player) => [player.id, player]));
    const positions: PlayerPosition[] = ['QB', 'RB', 'WR', 'TE', 'K', 'DST'];

    return positions.map((position) => {
      const startable = new Set(
        this.players
          .filter((p) => p.position === position && p.valueOverReplacement > 0)
          .map((p) => p.id)
      );
      const picked = recent.filter((pick) => byId.get(pick.playerId)?.position === position);
      const left = [...startable].filter((id) => !byId.get(id)?.isDrafted).length;
      return {
        position,
        taken: picked.length,
        window: recent.length,
        share: recent.length ? picked.length / recent.length : 0,
        left,
        // What the shelf held when the window opened, which is only the same as
        // `left + taken` while every pick in it was somebody worth having. Six
        // kickers off the bottom of the pool move `taken` and not `left`, and
        // adding them would report a shelf that was never there.
        leftBefore: left + picked.filter((pick) => startable.has(pick.playerId)).length,
      };
    });
  }

  /**
   * The tier currently being drafted out of at each position, and the step off it.
   *
   * The break is the best tier with anybody left in it: while it holds several
   * players waiting costs nothing, and the moment it empties the next name is
   * materially worse. Positions with nobody left at all are dropped rather than
   * reported as an infinitely deep cliff.
   */
  getTierBreaks(): TierBreak[] {
    const positions: PlayerPosition[] = ['QB', 'RB', 'WR', 'TE', 'K', 'DST'];
    const breaks: TierBreak[] = [];

    for (const position of positions) {
      const here = this.players.filter((p) => p.position === position);
      const open = here.filter((p) => !p.isDrafted);
      if (!open.length) continue;

      const tier = Math.min(...open.map((p) => p.tier));
      const inTier = open
        .filter((p) => p.tier === tier)
        .sort((a, b) => b.projectedPoints - a.projectedPoints);
      const below = open
        .filter((p) => p.tier > tier)
        .sort((a, b) => b.projectedPoints - a.projectedPoints);

      const worst = inTier[inTier.length - 1];
      const best = below[0];
      // Only a step both sides of which are being auctioned is a step in money:
      // an off-sheet player sits at the $1 floor, which is not a price anybody
      // would pay and would show as a cliff of the whole tier's value.
      const priced = best != null && this.forSale(worst) && this.forSale(best);

      breaks.push({
        position,
        tier,
        left: inTier.length,
        started: here.filter((p) => p.tier === tier).length,
        last: inTier.length === 1 ? inTier[0] : null,
        pointStep: best
          ? Math.max(0, Math.round(worst.projectedPoints - best.projectedPoints))
          : null,
        dollarStep: priced ? Math.max(0, worst.estimatedValue - best.estimatedValue) : null,
      });
    }

    return breaks;
  }

  /**
   * Replacement level per position, straight from the generated pool.
   *
   * Deliberately read rather than recomputed: it falls out of the league shape
   * in scripts/build-player-pool.mjs, and a second definition here would be a
   * third copy of LEAGUE to keep in step.
   */
  getReplacementLevel(position: PlayerPosition): number | null {
    return this.replacement[position] ?? null;
  }

  /** The league in force. Every value on the board was priced for exactly this. */
  getLeagueShape(): LeagueShape {
    return {
      ...this.league,
      positionLimits: { ...this.league.positionLimits },
      rostered: { ...this.league.rostered },
    };
  }

  /** The league the shipped pool was generated for, for showing what changed. */
  getPoolLeagueShape(): LeagueShape {
    return {
      ...POOL_LEAGUE,
      positionLimits: { ...POOL_LEAGUE.positionLimits },
      rostered: { ...POOL_LEAGUE.rostered },
    };
  }

  /**
   * How many players the pool actually holds at each position.
   *
   * A league may roster more of a position than exist in the pool — 32 teams
   * want 53 quarterbacks and there are 40 — and `replacementLevels` then falls
   * back to the worst one rather than erroring, which understates that
   * position's values. Nothing about that is visible from the board, so the
   * settings panel says it before a league is applied.
   */
  getPoolDepth(): Record<string, number> {
    const depth: Record<string, number> = {};
    for (const player of this.players) {
      depth[player.position] = (depth[player.position] ?? 0) + 1;
    }
    return depth;
  }

  /**
   * Give a team the name its owner answers to.
   *
   * Only one person runs this app while eleven others bid, so "Team 7" is a
   * number to hold in your head at exactly the moment there is no room for it.
   * Names cost nothing about the valuation, so unlike a league change this
   * leaves the draft entirely alone.
   */
  renameTeam(teamId: string, name: string): void {
    const trimmed = name.trim().slice(0, 40);
    const team = this.teams.find((t) => t.id === teamId);
    if (!team) return;

    const index = this.teams.indexOf(team);
    if (trimmed) this.teamNames[teamId] = trimmed;
    else delete this.teamNames[teamId];
    team.name = trimmed || `Team ${index + 1}`;

    writeStoredTeams({ names: this.teamNames, mine: this.myTeamId });
    this.announce();
  }

  /** Which team is the person running this, if they have said. */
  getMyTeamId(): string | null {
    return this.myTeamId;
  }

  /**
   * Say which team is yours.
   *
   * The whole point of watching eleven other rosters is to know what they can
   * still do to you; that only means anything once the app knows which one is
   * not an opponent.
   */
  setMyTeam(teamId: string | null): void {
    this.myTeamId = teamId && this.teams.some((t) => t.id === teamId) ? teamId : null;
    writeStoredTeams({ names: this.teamNames, mine: this.myTeamId });
    this.announce();
  }

  /**
   * What a league shape would do to prices, without committing to it.
   *
   * The settings panel changes numbers whose effect is invisible until you
   * apply them and lose the draft. Showing what the best player would cost lets
   * a shape be dialled against what the room actually pays — which, for a
   * format the model has never seen, is better evidence than the model.
   */
  getPricePreview(league: LeagueShape): { top: number; median: number; bought: number } {
    const entries = poolData.players as PoolEntry[];
    const wanted = normaliseLeague(league);

    /*
     * The stored sheet counts here only while the shape being previewed
     * auctions exactly as many players as the sheet names.
     *
     * This method takes a *hypothetical* league — the one being typed into the
     * settings panel — and an explicit mask overrides `auctionSheetSize`
     * entirely. Hand the mask over unconditionally and dragging "Players
     * auctioned" would show the current sheet's prices at every value of the
     * field: the number would move and the preview would not, which is worse
     * than showing nothing. Equal lengths is the one case where the field and
     * the list are saying the same thing. Anywhere else the field is the
     * question being asked, and it is answered from the size alone, which is
     * what that field is for.
     */
    const mask = this.sheetMask(entries);
    const usingSheet = mask && wanted.auctionSheetSize === this.sheet.ids.length;

    const { priced } = pricePool(
      entries.map((entry) => ({
        position: entry.position,
        points: entry.projection.points,
        receptions: entry.projection.receptions,
      })),
      wanted,
      usingSheet ? { onSheet: mask } : {}
    );
    const sold = priced
      .map((entry) => entry.auctionValue)
      .filter((value) => value > 1)
      .sort((a, b) => b - a);
    return {
      top: sold[0] ?? 0,
      median: sold[Math.floor(sold.length / 2)] ?? 0,
      bought: sold.length,
    };
  }

  /** The imported rankings in force, by player id. */
  getCustomRankings(): Record<string, RankingOverride> {
    return { ...this.overrides };
  }

  /**
   * How many players an import is currently speaking for.
   *
   * Counted by the prices stated rather than by the entries, because the two
   * stopped being the same number. The market board writes a rank for every
   * player so the board has one order in one space, but a price only for the
   * ones the money is buying — and a chip reading "Your ranks (642)" over a
   * board where 238 of those still carry our own number is a claim about whose
   * opinion is on screen, told wrong.
   */
  getCustomRankingCount(): number {
    return Object.values(this.overrides).filter((override) => override.value != null).length;
  }

  /**
   * Lay an imported ranking over the board.
   *
   * Unlike a league change this does not invalidate picks already made — the
   * money spent is still the money spent — so a draft in progress survives it.
   * Only what the remaining players are said to be worth moves.
   */
  setCustomRankings(overrides: Record<string, RankingOverride>): void {
    // Stated until proven derived: `applyConsensusBoard` sets the marker back
    // immediately after calling this, and an imported CSV never does.
    this.forgetMarketBoard();
    this.overrides = { ...overrides };
    writeStoredOverrides(this.overrides);
    this.repriceInPlace();
    this.announce();
  }

  /**
   * Re-price the board at the market's ordering, from the consensus already in
   * the pool.
   *
   * This is the board `npm run backtest` measured and preferred. Sweeping
   * blends of our ordering against real pre-season ADP, the best weight on our
   * own was zero in all three held-out seasons and under leave-one-season-out:
   * the market alone scored 0.510, 0.482 and 0.481 on surplus over
   * replacement against our 0.368, 0.378 and 0.428. So this is not a fallback
   * for a night the import fails; it is the recommended board.
   *
   * It goes through `setCustomRankings` rather than being a second pricing
   * mode, because an imported CSV and the built-in consensus are the same
   * claim from different sources — somebody else's ordering, our dollars — and
   * a second path would be a second place a price is decided. Everything the
   * import already earns comes free: the advisor follows it, `modelValue`
   * keeps ours beside it, and a draft in progress survives it.
   *
   * Returns the coverage, because the honest number is not 628. FantasyPros
   * ranks 383 of them; the rest keep our price and are the dollar players it
   * does not bother with.
   */
  applyConsensusBoard(): { ranked: number; of: number; fromAdp: number; fromConsensus: number } {
    const subjects = this.marketSubjects();
    this.setCustomRankings(consensusOverrides(subjects));
    // After setCustomRankings, which clears it: these values are derived, so
    // they have to be re-derived whenever the curve underneath them moves.
    try {
      localStorage.setItem(MARKET_BOARD_KEY, '1');
    } catch {
      // A browser refusing storage costs the re-derive, not the board.
    }
    return consensusCoverage(subjects);
  }

  private forgetMarketBoard(): void {
    try {
      localStorage.removeItem(MARKET_BOARD_KEY);
    } catch {
      // Nothing to do; the marker is an optimisation, not a source of truth.
    }
  }

  /** Whether the prices on the board were derived by us rather than stated. */
  private marketBoardInForce(): boolean {
    if (!Object.keys(this.overrides).length) return false;
    try {
      return !!localStorage.getItem(MARKET_BOARD_KEY);
    } catch {
      return false;
    }
  }

  /**
   * Re-derive the market board after anything that moves the curve under it.
   *
   * The bug this exists for was found driving a real commissioner's sheet.
   * "Use consensus" reads dollar values off our surplus curve for a board where
   * the money buys 192 players; importing a sheet re-prices that curve for a
   * board where the same money buys sixty. The overrides then held the old
   * numbers and won, because `buildPlayer` prefers an override to the price it
   * just computed — so the whole sheet read about 35% cheap. Gibbs showed $55
   * against the $94 the room would actually pay, which is a board that loses
   * every player while its owner believes he is being disciplined. And it
   * happened in the order somebody would naturally use: press the recommended
   * button, then paste the sheet when the commissioner sends it.
   */
  private refreshMarketBoard(): void {
    if (!this.marketBoardInForce()) return;
    this.applyConsensusBoard();
  }

  /**
   * When to buy, which is the half `getSpendOutlook` does not answer.
   *
   * Rests on a constraint rather than a forecast: the money still in the room
   * divided by the sheet players still for sale is what the rest must average,
   * whatever anybody at the table believes. Every auction ends in a fire sale
   * because the money runs out before the players do, and the only question is
   * whether you are holding money when it starts.
   *
   * `moneyLeft` comes from `getInflationBasis` rather than being summed again
   * here — it is the same quantity, already net of the dollar-a-slot reserve,
   * and a second summation is a second answer to how rich the room is.
   */
  getEndgame(): Endgame {
    const basis = this.getInflationBasis();
    // Newest first, and auction sales only: a snake pick costs nothing and
    // averaging zeroes into a price would report a room that had stopped paying.
    const recentSales = [...this.history]
      .reverse()
      .filter((pick) => (pick.phase ?? 'auction') === 'auction' && pick.cost != null);
    // What each of those went for, and what the board said he was worth. The
    // second is what stops the pace being a reading of the auction's shape
    // rather than of the room: the players sold first are the dear ones, so a
    // raw pace beats par from the opening sale whatever anybody paid.
    //
    // The list price rather than tonight's adjusted one, deliberately: the
    // adjusted price already carries the multiplier this comparison is meant
    // to be independent of, so dividing by it would compare the room with
    // itself and report agreement always.
    const priced = new Map(this.players.map((player) => [player.id, player.modelValue]));
    return endgame({
      moneyLeft: basis.moneyLeft,
      playersLeft: basis.forSaleLeft,
      recentPrices: recentSales.map((pick) => pick.cost as number),
      recentList: recentSales.map((pick) => priced.get(pick.playerId) ?? 0),
      teams: this.teams.map((team) => ({
        id: team.id,
        name: team.name,
        remaining: team.remaining,
      })),
      myTeamId: this.myTeamId,
    });
  }

  /**
   * What the snake will hand you free, and therefore what a bid is buying.
   *
   * The arithmetic specific to this format, and the piece nobody else at the
   * table is doing. `vorp` measures a player against the last man the *league*
   * rosters — the sixtieth receiver — which is the right bar only when the
   * auction buys the whole roster. Here it does not: the alternative is
   * whoever survives to your own snake slot, and paying for the gap to the
   * sixtieth receiver when you are only buying the gap to the twenty-fifth is
   * how a budget disappears into players you did not need to buy.
   *
   * The ordering the room is assumed to snake in comes through `marketOrder`,
   * the same rule the consensus board uses, rather than off the live price:
   * every off-sheet player is priced at the dollar floor by construction, so
   * price cannot order the snake pool at all.
   */
  getSpendOutlook(): SnakeOutlook {
    const positions: string[] = ['RB', 'WR', 'TE', 'QB', 'K', 'DST'];
    if (this.league.auctionSheetSize === null) {
      return {
        positions: null,
        atOverall: null,
        reason:
          'This league auctions the whole board, so there is no snake half to measure against.',
      };
    }
    const mine = this.myTeamId;
    if (!mine) {
      return {
        positions: null,
        atOverall: null,
        reason:
          'Mark which team is yours in league settings — an outlook without it is somebody else’s draft.',
      };
    }
    if (!this.hasSnakeOrder()) {
      return {
        positions: null,
        atOverall: null,
        reason: 'Set the snake order first; where you pick is what decides what survives to you.',
      };
    }

    // Where you pick next, counted among snake picks. During the auction this
    // walks the order from the start, which is exactly the projected snake.
    const upcoming = this.getSnakeUpcoming(this.teams.length * 3);
    const yours = upcoming.find((slot) => slot.team.id === mine);
    if (!yours) {
      return {
        positions: null,
        atOverall: null,
        reason: 'Your roster is full — the snake has nothing left to hand you.',
      };
    }

    // One ordering for the whole board, so a snake pick and an auction buy are
    // ranked by the same rule. Anybody neither source ranks sorts after
    // everybody either source does, keeping our own model as the tail-breaker.
    const ranked = marketOrder(this.marketSubjects());
    const order = new Map(ranked.map((entry, index) => [entry.gsis, index]));
    const subject = (player: Player) => ({
      id: player.id,
      name: player.name,
      position: player.position,
      points: player.projectedPoints,
      price: player.estimatedValue,
      order: order.get(player.id) ?? ranked.length + player.adp,
    });

    const live = this.players.filter((player) => !player.isDrafted);
    return snakeOutlook({
      snakePool: live.filter((player) => !player.onSheet).map(subject),
      forSale: live.filter((player) => player.onSheet).map(subject),
      yourNextSnakePick: yours.overall,
      positions,
    });
  }

  /**
   * The same outlook before the order is drawn, as a range rather than a number.
   *
   * The commissioner draws the snake order at the table, sometimes on the
   * night, and until he does `getSpendOutlook` refuses — correctly, because an
   * outlook computed at somebody else's pick is somebody else's draft. What
   * that leaves is a month of not being able to plan the one thing this format
   * turns on, which is a high price for a refusal that was only ever about a
   * single missing input.
   *
   * So: run it at every draw and report the bound. Nothing is assumed here that
   * `snakeOutlook` does not already assume, and the answer is exact — the true
   * value is one of the twelve, and every one of them is in the range.
   *
   * It refuses on everything else exactly as the outlook does, because those
   * refusals are about facts nobody can bound: with no sheet there is no snake
   * half, and with no team marked there is no roster to measure against.
   */
  getSpendSpread(positions: readonly string[] = ['QB', 'RB', 'WR', 'TE']): SnakeSpread {
    if (this.league.auctionSheetSize === null) {
      return {
        positions: null,
        reason:
          'This league auctions the whole board, so there is no snake half to measure against.',
      };
    }
    if (!this.myTeamId) {
      return {
        positions: null,
        reason:
          'Mark which team is yours in league settings — an outlook without it is somebody else’s draft.',
      };
    }

    const ranked = marketOrder(this.marketSubjects());
    const order = new Map(ranked.map((entry, index) => [entry.gsis, index]));
    const subject = (player: Player) => ({
      id: player.id,
      name: player.name,
      position: player.position,
      points: player.projectedPoints,
      price: player.estimatedValue,
      order: order.get(player.id) ?? ranked.length + player.adp,
    });
    const live = this.players.filter((player) => !player.isDrafted);
    return snakeOutlookSpread(
      {
        snakePool: live.filter((player) => !player.onSheet).map(subject),
        forSale: live.filter((player) => player.onSheet).map(subject),
        positions,
      },
      // Every seat in the first round: your first snake pick is your place in
      // the order, so the draw is exactly one through the number of teams.
      Array.from({ length: this.teams.length }, (_, index) => index + 1)
    );
  }

  /**
   * The inputs a plan is solved from, or null with the reason it cannot be.
   *
   * Assembled from exactly the same places the outlook is — the sheet for what
   * is for sale, the market's order for who the room takes before you, your own
   * roster for which seats are still open — so the plan and the per-player gain
   * can never come to different conclusions about the same board.
   */
  private planInput(
    /** The snake values every undrafted player; the auction only what is for sale. */
    scope: 'auction' | 'everyone' = 'auction'
  ): { input: PlanInput; reason: null } | { input: null; reason: string } {
    /*
     * Where you pick is an input, not a precondition.
     *
     * The outlook refuses without a drawn order, correctly — computed at
     * somebody else's seat it is somebody else's draft. The plan was then
     * solved at the seat that helps *least*, which was safe and wrong in a
     * knowable direction: it understated every gap on the board for the eleven
     * draws out of twelve you are not going to get.
     *
     * The draw is uniform over the seats and nobody knows it, so the honest
     * baseline is the *expected* free man at each rank — averaged over all
     * twelve, element by element. One plan, no caveat, and it stops being a
     * question the owner has to answer before the tool will work. Once the
     * commissioner does draw the order this uses the real seat instead: an
     * average over draws you now know you did not get is worse than the one
     * you did.
     */
    const outlooks: SnakeOutlook[] = [];
    if (this.hasSnakeOrder() && this.myTeamId) {
      const exact = this.getSpendOutlook();
      if (exact.positions) outlooks.push(exact);
    }
    if (!outlooks.length) {
      for (let seat = 1; seat <= this.teams.length; seat += 1) {
        const at = this.outlookAtPick(seat);
        if (!at.positions)
          return { input: null, reason: at.reason ?? 'No outlook to plan against.' };
        outlooks.push(at);
      }
    }

    const team = this.teams.find((entry) => entry.id === this.myTeamId);
    if (!team) return { input: null, reason: 'No team is marked as yours.' };

    // Element-wise, so the n-th free man is the average n-th free man rather
    // than the n-th of some averaged list — different numbers, and only the
    // first is the one a purchase actually displaces.
    const freeByPosition: Record<string, readonly number[]> = {};
    for (const position of outlooks[0].positions ?? []) {
      const lists = outlooks.map(
        (outlook) =>
          outlook.positions?.find((entry) => entry.position === position.position)?.freeRanked ?? []
      );
      const deepest = Math.max(...lists.map((list) => list.length));
      const averaged: number[] = [];
      for (let rank = 0; rank < deepest; rank += 1) {
        const have = lists
          .map((list) => list[rank])
          .filter((value): value is number => value != null);
        if (!have.length) break;
        averaged.push(have.reduce((sum, value) => sum + value, 0) / have.length);
      }
      freeByPosition[position.position] = averaged;
    }

    // Seats still open, the flex counted separately — the plan decides which
    // position fills it, which is the whole reason a flex moves prices.
    const openSeats: Record<string, number> = {};
    for (const [position, seats] of Object.entries(this.league.startingLineup)) {
      if (position === 'FLEX') continue;
      openSeats[position] = Math.max(0, seats - (team.roster[position as PlayerPosition] ?? 0));
    }
    const spare = FLEX_ELIGIBLE.reduce(
      (total, eligible) =>
        total +
        Math.max(0, (team.roster[eligible] ?? 0) - (this.league.startingLineup[eligible] ?? 0)),
      0
    );
    const flexOpen = Math.max(0, (this.league.startingLineup.FLEX ?? 0) - spare);

    // Tonight's price rather than the list one: a plan is about what you will
    // actually pay, and inflation is exactly the difference between the two.
    const adjust = this.getPriceAdjuster();
    const candidates: PlanCandidate[] = this.players
      .filter(
        (player) =>
          !player.isDrafted && !player.marketOnly && (scope === 'everyone' || player.onSheet)
      )
      .map((player) => ({
        id: player.id,
        name: player.name,
        position: player.position,
        price: Math.max(1, Math.round(adjust.price(player))),
        points: player.projectedPoints,
      }));

    return {
      input: {
        candidates,
        freeByPosition,
        openSeats,
        flexOpen,
        flexPositions: FLEX_ELIGIBLE,
        budget: Math.max(0, this.spendableFor(team).spendable),
      },
      reason: null,
    };
  }

  /**
   * The same outlook at a seat you name, rather than the one you were dealt.
   *
   * The commissioner draws the order at the table, sometimes on the night, and
   * everything downstream of `getSpendOutlook` refuses until he does — which is
   * correct, and leaves a month in which the one number this format turns on
   * cannot be looked at. This is the seam `getSpendSpread` already uses to
   * bound the outlook across every draw; the plan wants it too.
   */
  private outlookAtPick(pick: number): SnakeOutlook {
    if (this.league.auctionSheetSize === null) {
      return {
        positions: null,
        atOverall: null,
        reason:
          'This league auctions the whole board, so there is no snake half to measure against.',
      };
    }
    if (!this.myTeamId) {
      return {
        positions: null,
        atOverall: null,
        reason:
          'Mark which team is yours in league settings — an outlook without it is somebody else’s draft.',
      };
    }
    const ranked = marketOrder(this.marketSubjects());
    const order = new Map(ranked.map((entry, index) => [entry.gsis, index]));
    const subject = (player: Player) => ({
      id: player.id,
      name: player.name,
      position: player.position,
      points: player.projectedPoints,
      price: player.estimatedValue,
      order: order.get(player.id) ?? ranked.length + player.adp,
    });
    const live = this.players.filter((player) => !player.isDrafted);
    return snakeOutlook({
      snakePool: live.filter((player) => !player.onSheet).map(subject),
      forSale: live.filter((player) => player.onSheet).map(subject),
      yourNextSnakePick: pick,
      positions: ['RB', 'WR', 'TE', 'QB', 'K', 'DST'],
    });
  }

  /**
   * The best roster the remaining money can still buy, and what a dollar is
   * worth under it.
   *
   * The one question every other panel in this app was answering around rather
   * than answering. See `src/lib/rosterPlan.ts` for why the objective is the
   * lineup's points and not a sum of per-player gains.
   */
  getRosterPlan(): RosterPlan {
    const { input, reason } = this.planInput();
    if (!input) {
      return { buy: [], spend: 0, gain: 0, perDollar: 0, curve: [0], slack: 0, reason };
    }
    return rosterPlan(input);
  }

  /**
   * The most this player is worth to you, given everything else the money could
   * buy instead.
   *
   * Replaces a `riskAdjustedValue * 1.15` that ranked players in exactly the
   * order their prices already did — so the panel headed *What to bid* carried
   * no information the price beside it did not, and on the shipped board it
   * told the owner to go to $28 on a man whose gain over the free back is minus
   * forty-two points.
   *
   * Null when a plan cannot honestly be computed at all, which is the same set
   * of refusals the outlook makes: no sheet, no team marked, no order drawn.
   */
  /**
   * What every player for sale is worth to this roster, in one pass.
   *
   * The plan is one knapsack; valuing the whole board against it is a map read
   * per player afterwards. That is what makes it affordable to answer "what
   * should I pay for him" for all sixty rather than only for whoever happens to
   * be on the block — which was the shape of the previous version, and the
   * reason it could not put a price on the fifty-nine names that had not been
   * called yet.
   */
  getBidBoard(): Map<string, PlayerValue> {
    const { input } = this.planInput();
    if (!input) return new Map();
    return valueBoard(input, rosterPlan(input));
  }

  /**
   * Every undrafted player, ranked by what he adds to *this* lineup.
   *
   * The snake's version of the same question, and the reason it is the same
   * function: a free pick and a bid differ in what they cost, not in what they
   * are worth. Ranking by projected points is close and not the same — with the
   * dedicated seats full and a flex open, the man who helps most is the one
   * with the widest gap to whoever else would fill that seat, and those two
   * orderings part company exactly when a roster starts filling up.
   *
   * Prices are carried and ignored: nothing in the snake costs money.
   */
  getPickBoard(): Map<string, PlayerValue> {
    const { input } = this.planInput('everyone');
    if (!input) return new Map();
    return valueBoard(input, rosterPlan(input));
  }

  /**
   * The most this player is worth to you, at the rate the plan sets.
   *
   * Capped at what the rules actually allow, because a ceiling the engine would
   * refuse is worse than no ceiling — the same bar `getBidCompetition` is held
   * to. Zero survives only where the roster cannot legally carry him.
   */
  maxPriceFor(playerId: string): number | null {
    const player = this.players.find((entry) => entry.id === playerId);
    const team = this.teams.find((entry) => entry.id === this.myTeamId);
    if (!player || !team) return null;
    if (!this.checkRoster(player, team).ok) return 0;
    const value = this.getBidBoard().get(playerId);
    if (!value) return null;
    return Math.min(value.maxPrice, Math.max(0, this.spendableFor(team).spendable));
  }

  /**
   * What buying *this* player gains over the free alternative at his position.
   *
   * The panel version ranks positions; this is the same arithmetic pointed at
   * the man on the block, which is the number somebody needs while money is on
   * the table. Null when the outlook cannot honestly be computed at all.
   */
  gainOverSnake(playerId: string): SnakeGain | null {
    const outlook = this.getSpendOutlook();
    if (!outlook.positions) return null;
    const player = this.players.find((entry) => entry.id === playerId);
    if (!player || player.marketOnly) return null;
    const mine = this.teams.find((team) => team.id === this.myTeamId);
    if (!mine) return null;
    return this.gainAgainst(
      player,
      mine,
      (pos) => outlook.positions?.find((row) => row.position === pos)?.free ?? null
    );
  }

  /**
   * What the draft has done to each position, recomputed on every pick.
   *
   * Everything else on a card is a fact about the player and reads the same at
   * pick one and pick a hundred and fifty. These four readings are the ones
   * that move, and they are the reason an auction is played rather than
   * calculated: what is left, how fast it is going, whether you still need one,
   * and who can still outbid you.
   *
   * All of it is per *position* rather than per player, which is what makes it
   * affordable. Sixty cards ask four questions each; there are six answers, and
   * a card at a position nothing happened to keeps the object it already had —
   * see `usePositionPulse` in the room, which is where that stabilising is
   * done. Without it every pick would re-render the whole board, which is the
   * cost this board was measured and fixed for once.
   */
  getPositionPulse(): Map<string, PositionPulse> {
    const out = new Map<string, PositionPulse>();
    const mine = this.teams.find((team) => team.id === this.myTeamId) ?? null;

    /*
     * The last ten transactions, whatever half of the draft they happened in.
     *
     * Supply counts both halves. A receiver taken in the snake is exactly as
     * unavailable as one bought for forty dollars — waiting for him is no
     * longer an option, which is the whole question a run is asking — so this
     * window does not filter on phase. Money is the thing that only counts the
     * auction, and no money is read here.
     */
    const window = this.history.slice(-RUN_WINDOW);
    const byId = new Map(this.players.map((player) => [player.id, player]));
    const recent = window
      .map((pick) => byId.get(pick.playerId)?.position ?? null)
      .filter((position): position is Position => position != null);

    /*
     * Both halves hoisted out of the position loop, which is the difference
     * between this costing something and costing nothing.
     *
     * `spendableFor` does not depend on the position at all — it is a fact
     * about a team's money — so calling it inside the loop asked the same
     * twelve questions six times over. And bucketing the board once beats
     * filtering all six hundred players once per position. Nominating went
     * from 1099ms under a 4x throttle to a figure worth keeping.
     */
    const spendable = new Map(
      this.teams.map((team) => [team.id, this.spendableFor(team).spendable])
    );
    const buckets = new Map<string, Player[]>();
    for (const player of this.players) {
      if (player.isDrafted || player.marketOnly) continue;
      const bucket = buckets.get(player.position);
      if (bucket) bucket.push(player);
      else buckets.set(player.position, [player]);
    }
    for (const bucket of buckets.values())
      bucket.sort((a, b) => b.projectedPoints - a.projectedPoints);

    for (const position of POSITIONS) {
      const live = buckets.get(position) ?? [];
      const replacement = this.replacement[position] ?? 0;

      /*
       * Who could still take him off you, at this position.
       *
       * A team with no room at the position is not a quiet bidder — it cannot
       * bid at any price — so it is left out rather than listed at zero, which
       * is the rule `getBidCompetition` already lives by. The ceiling is
       * `spendableFor`, the same call `validateBid` makes, because a number the
       * room reads off a card and the engine then refuses is worse than no
       * number at all.
       */
      const rivals: number[] = [];
      let myCeiling = 0;
      let myOpenings = 0;
      for (const team of this.teams) {
        const money = Math.max(0, spendable.get(team.id) ?? 0);
        if (team.id === this.myTeamId) {
          myCeiling = money;
          myOpenings = unfilledSlotsFor(position, team.roster, this.league);
          continue;
        }
        const capped = (team.roster[position] ?? 0) >= (this.league.positionLimits[position] ?? 0);
        if (!capped) rivals.push(money);
      }
      rivals.sort((a, b) => b - a);

      out.set(position, {
        position,
        // Capped, because a shelf of two hundred receivers is a texture rather
        // than a reading. The count beside it is the honest total.
        shelf: live.slice(0, SHELF_DEPTH).map((player) => Math.round(player.projectedPoints)),
        left: live.length,
        startable: live.filter((player) => player.projectedPoints > replacement).length,
        replacement: Math.round(replacement),
        goneRecently: recent.filter((entry) => entry === position).length,
        window: recent.length,
        slotsTotal: this.league.startingLineup[position] ?? 0,
        slotsFilled: mine
          ? Math.min(mine.roster[position] ?? 0, this.league.startingLineup[position] ?? 0)
          : 0,
        // A flex seat only exists if the league has one and this position may
        // fill it; a quarterback's card must not offer one it cannot use.
        flexOpen:
          mine != null &&
          FLEX_ELIGIBLE.includes(position as Position) &&
          myOpenings >
            Math.max(0, (this.league.startingLineup[position] ?? 0) - (mine.roster[position] ?? 0)),
        myCeiling,
        rivals,
      });
    }
    return out;
  }

  /**
   * Every player's gain over the free man, in one pass.
   *
   * `gainOverSnake` builds a whole outlook per call — a market sort over six
   * hundred players — which is fine for the one man on the block and ruinous
   * for a board of sixty cards. The outlook is the same for all of them, so it
   * is computed once here and each player costs a lookup and a subtraction.
   *
   * The roster-aware bar comes with it. Quoting the position-level gain for a
   * third running back when your two slots are full is the specific way this
   * format is lost, so the card gets the same starter/flex/bench answer the
   * stage does rather than a cheaper approximation of it.
   *
   * Both ends are reported. With an order drawn they are equal and the card
   * prints one number; before one is drawn they bound it, which is the honest
   * thing to put on a browsing surface a month before the draw.
   */
  getBoardGains(): Map<string, { low: number; high: number; free: string | null; slot: string }> {
    const out = new Map<string, { low: number; high: number; free: string | null; slot: string }>();
    const mine = this.teams.find((team) => team.id === this.myTeamId);
    if (!mine) return out;

    const exact = this.getSpendOutlook();
    const spread = exact.positions ? null : this.getSpendSpread(['QB', 'RB', 'WR', 'TE']);
    if (!exact.positions && !spread?.positions) return out;

    const lowAt = (position: string) =>
      exact.positions
        ? (exact.positions.find((row) => row.position === position)?.free ?? null)
        : (spread!.positions!.find((row) => row.position === position)?.bestFree ?? null);
    const highAt = (position: string) =>
      exact.positions
        ? (exact.positions.find((row) => row.position === position)?.free ?? null)
        : (spread!.positions!.find((row) => row.position === position)?.worstFree ?? null);

    for (const player of this.players) {
      if (player.isDrafted || player.marketOnly) continue;
      const low = this.gainAgainst(player, mine, lowAt);
      const high = this.gainAgainst(player, mine, highAt);
      if (!low || !high) continue;
      out.set(player.id, {
        low: low.gain,
        high: high.gain,
        free: high.free,
        slot: high.slot,
      });
    }
    return out;
  }

  /**
   * The same number bounded across every draw, for before the order exists.
   *
   * The stage is where a bid is decided, so a gain that only the plan panel can
   * show is a gain nobody has at the moment a name is called — the argument
   * `modelTrust` already makes for putting the blind spots beside the name.
   * Until the commissioner draws the order this is what there is, and it is a
   * bound rather than an estimate: the true figure is one of the twelve.
   *
   * `settled` is the field that earns it. At quarterback and tight end the two
   * ends are the same man and the same number, so the line reads as a fact and
   * the bid can be decided now; at running back it is 82 against Josh Jacobs
   * picking first and 124 against RJ Harvey picking last, and the room deserves
   * to see that it is a range rather than being handed whichever end the team
   * list happened to imply.
   */
  gainOverSnakeBounds(playerId: string): { low: SnakeGain; high: SnakeGain } | null {
    const spread = this.getSpendSpread(['QB', 'RB', 'WR', 'TE']);
    if (!spread.positions) return null;
    const player = this.players.find((entry) => entry.id === playerId);
    if (!player || player.marketOnly) return null;
    const mine = this.teams.find((team) => team.id === this.myTeamId);
    if (!mine) return null;

    const pick = (which: 'bestFree' | 'worstFree') => (pos: string) =>
      spread.positions?.find((row) => row.position === pos)?.[which] ?? null;
    // The best free man gives the smallest gain, because the gain is measured
    // against him: a better alternative is a worse bid.
    const low = this.gainAgainst(player, mine, pick('bestFree'));
    const high = this.gainAgainst(player, mine, pick('worstFree'));
    return low && high ? { low, high } : null;
  }

  /**
   * Which free man a bid actually replaces, given your roster — one copy.
   *
   * Called with the outlook's free men when the order is known and with each
   * end of the spread when it is not. A second copy of this would be a second
   * answer to whether a bid buys a starter, a flex or a bench body, and the two
   * would part company at exactly the moment a roster filled up.
   */
  private gainAgainst(
    player: Player,
    mine: Team,
    at: (position: string) => { id: string; name: string; points: number } | null
  ): SnakeGain | null {
    const position = player.position as Position;
    const openHere = Math.max(
      0,
      (this.league.startingLineup[position] ?? 0) - mine.roster[position]
    );
    const startable = unfilledSlotsFor(position, mine.roster, this.league) > 0;

    /*
     * Which man he actually replaces, which is not always the best free player
     * at his own position.
     *
     * This is the mistake that loses a hybrid draft. Once your two running back
     * slots are full, a third back does not buy you the gap to the best free
     * back — that seat is taken. He is competing for your flex, where the
     * alternative is the best free player from *any* flex-eligible position,
     * which is a higher bar. And once the flex is gone too he is a bench body:
     * he adds nothing to the lineup that scores, whatever his projection says.
     *
     * The board will still happily quote a big number for him, because the
     * number is about the player. This is about the player *and your roster*.
     */
    if (!startable) {
      return {
        gain: 0,
        free: null,
        freeId: null,
        freePoints: null,
        slot: 'bench',
        note: `Your ${position} slots and flex are full — he is a bench player and adds nothing to the lineup that scores.`,
      };
    }

    if (openHere > 0) {
      const free = at(position);
      if (!free) return null;
      return {
        gain: Math.round(player.projectedPoints - free.points),
        free: free.name,
        freeId: free.id,
        freePoints: free.points,
        slot: 'starter',
        note: `Fills your ${position}${(mine.roster[position] ?? 0) + 1}.`,
      };
    }

    // The flex, where he competes with every position that can fill it.
    const rivals = FLEX_ELIGIBLE.map((pos) => at(pos)).filter(
      (entry): entry is NonNullable<typeof entry> => entry != null
    );
    const best = rivals.reduce<(typeof rivals)[number] | null>(
      (top, entry) => (top == null || entry.points > top.points ? entry : top),
      null
    );
    if (!best) return null;
    return {
      gain: Math.round(player.projectedPoints - best.points),
      free: best.name,
      freeId: best.id,
      freePoints: best.points,
      slot: 'flex',
      note: `Your ${position} slots are full — he is competing for your flex, against every position that can fill it.`,
    };
  }

  /** What the market says, or null when no snapshot is bundled. */
  /** When the pool was built. What ages in it is the roster and injury snapshot. */
  getPoolGeneratedAt(): string | null {
    return (poolData as { generatedAt?: string }).generatedAt ?? null;
  }

  getMarketSnapshot(): MarketSnapshot | null {
    return AuctionDraftService.market;
  }

  /** What the board would cover, without applying anything. */
  previewConsensusBoard(): { ranked: number; of: number; fromAdp: number; fromConsensus: number } {
    return consensusCoverage(this.marketSubjects());
  }

  /**
   * The board's players as the market module wants them.
   *
   * `auctionValue` is `modelValue` and never the live price: applying the
   * market board twice has to land where applying it once did, and off the
   * live price the second press would re-order an already re-ordered board.
   */
  private marketSubjects() {
    const adp = AuctionDraftService.adpByGsis;
    const absent = AuctionDraftService.adpByAbsentee;
    return this.players.map((player) => ({
      gsis: player.id,
      position: player.position,
      auctionValue: player.modelValue,
      consensusRank: player.market?.consensusRank ?? null,
      // A market-only player has no gsis and no projection; his ADP is the only
      // thing anybody knows about him, and it is exactly what this needs.
      adp: adp.get(player.id) ?? absent.get(player.id) ?? null,
      // The reorder is a permutation of a value curve, so it has to stay inside
      // the set the money is spread across; a sheet player swapped for an
      // off-sheet one moves budget out of the auction entirely.
      forSale: player.onSheet,
    }));
  }

  /** Drop the import and go back to what the model says. */
  clearCustomRankings(): void {
    if (!Object.keys(this.overrides).length) return;
    this.forgetMarketBoard();
    this.overrides = {};
    writeStoredOverrides(this.overrides);
    this.repriceInPlace();
    this.announce();
  }

  // -------------------------------------------------------------------------
  // the commissioner's sheet
  //
  // A sheet size is our guess at the list; this is the list. It changes what
  // the money is buying, which changes every price on the board — but it
  // changes no rule, so unlike a league change a draft in progress survives it.
  // -------------------------------------------------------------------------

  /** The sheet in force: who is being auctioned, and who went unsold. */
  getAuctionSheet(): StoredSheet {
    return { ids: [...this.sheet.ids], unsold: [...this.sheet.unsold] };
  }

  /**
   * Open on the board this build is actually for.
   *
   * The app used to open on a league nobody plays — full PPR, no flex, the whole
   * board auctioned — because that is the shape the pool file happens to have
   * been priced at, and the first-run gate existed to say so out loud. Three
   * things then had to be done by hand before the board meant anything:
   * confirm the league, paste sixty names, and press "Use consensus". Each is a
   * step with a failure mode, and all three have to be repeated on any fresh
   * browser — including the published artifact on a phone, which is the machine
   * this gets opened on at eleven at night when the laptop has died. Pasting
   * sixty names on a phone is not going to happen.
   *
   * So they are defaults now. `HOME_LEAGUE` settles the league; this settles
   * the other two, on an empty browser, once.
   *
   * The order is load-bearing and is the one bug this file has already been
   * caught by: "Use consensus" reads dollar values off the surplus curve for
   * whatever board is in force, and applying a sheet re-prices that curve for a
   * board where the same money buys sixty. Seeding them the other way round
   * would leave the whole sheet reading about 35% cheap. `setAuctionSheet`
   * re-derives the market board itself, so sheet-then-market is right twice
   * over.
   *
   * It refuses on anything that means somebody has already been here: a marker
   * from a previous seed, a stored sheet, a stored league, custom rankings, or
   * a draft in progress. That is why it has to be called *after* `restore()` —
   * a browser resuming an afternoon's work must not have a sheet applied
   * underneath it.
   */
  seedHomeDefaults(): { sheet: number; market: number; mine: string | null } | null {
    try {
      if (localStorage.getItem(HOME_SEEDED_KEY)) return null;
    } catch {
      // No storage means no way to remember having seeded, and a seed that
      // repeats every load would undo the owner's own choices. Do nothing.
      return null;
    }
    const untouched =
      !this.history.length && !this.sheet.ids.length && !Object.keys(this.overrides).length;
    try {
      localStorage.setItem(HOME_SEEDED_KEY, new Date().toISOString());
    } catch {
      return null;
    }
    if (!untouched) return null;

    const sheet = this.setAuctionSheet(this.resolveHomeSheet());
    const market = sheet ? this.applyConsensusBoard().ranked : 0;

    /*
     * And one of the twelve is yours.
     *
     * This looks like the guess three panels were already caught making, and it
     * is the opposite of it. Those bugs read `activeTeam` — the winning-team
     * select, which names whoever just *bought* a player and therefore sits on
     * an opponent most of the night — and silently presented an opponent's
     * roster as the owner's. Nothing here is inferred from anything: the twelve
     * team slots are arbitrary labels the owner assigns as the auction runs, so
     * "you are the first one" is a naming convention, not a claim about the
     * world, and the first-run gate he has to pass through says so with a
     * picker beside it.
     *
     * What it costs to leave null is four things inert on a fresh browser, and
     * one of them is the number this whole format turns on: `gainOverSnake`
     * reads your own roster to say whether a bid buys a starter, a flex or a
     * bench body, and refuses — rightly — when it does not know whose roster to
     * read. The budget rail's highlight, the budget planner and the advisor go
     * with it. A default that is visible and one click from being changed beats
     * four panels that say "no team is marked as yours".
     */
    const mine = this.myTeamId ?? this.teams[0]?.id ?? null;
    if (mine && !this.myTeamId) this.setMyTeam(mine);
    return { sheet, market, mine };
  }

  /**
   * The bundled sixty, resolved against this pool by the panel's own parser.
   *
   * Unmatched names are dropped rather than guessed at, exactly as a paste's
   * are — a name matching two players matches neither. A pool rebuild that
   * stopped matching a name therefore shortens the seeded sheet rather than
   * binding the wrong man, and `npm run refresh` reports the same loss against
   * the same file on draft morning.
   */
  private resolveHomeSheet(): string[] {
    const candidates = this.players.map((player) => ({
      id: player.id,
      name: player.name,
      position: player.position,
      team: player.team,
    }));
    return readAuctionSheet(HOME_SHEET_TEXT, candidates)
      .resolutions.filter((row) => row.status === 'matched')
      .map((row) => row.player.id);
  }

  /** How many players the imported sheet names. Zero when there is no sheet. */
  getSheetCount(): number {
    return this.sheet.ids.length;
  }

  /**
   * Apply the commissioner's actual sheet.
   *
   * This is an import, not a league change. A sheet touches no roster rule and
   * only ever loosens the reserve — which this format already holds at zero —
   * so every pick already made stays exactly as legal as it was, and the draft
   * in progress survives. That is the same reasoning a rankings import runs on.
   *
   * The league's `auctionSheetSize` is pinned to the length of the list,
   * because a size and a list are two statements of one fact and a board priced
   * off one while a panel reports the other cannot be read. `LeagueSettings`
   * makes that field read-only for the same reason.
   *
   * Moving the league is what makes the stashed draft need re-stamping below:
   * `clearedPickCount` and `restoreClearedDraft` both refuse a stash bid under
   * a different league, and that net exists because Reset once destroyed an
   * afternoon's work. Importing a list is not a reason to quietly cut it.
   *
   * Returns how many of the ids the pool actually knows.
   */
  setAuctionSheet(ids: readonly string[], loss?: number): number {
    const known = new Set(this.players.map((player) => player.id));
    const wanted = [...new Set(ids)].filter((id) => known.has(id));
    if (!wanted.length || this.tooConcentrated(wanted)) return 0;

    const onSheet = new Set(wanted);
    this.sheet = {
      ids: wanted,
      unsold: this.sheet.unsold.filter((id) => onSheet.has(id)),
      // Only on the first sheet: replacing one sheet with another must not
      // forget the size the board had before any of them arrived.
      priorSize: this.sheet.ids.length ? this.sheet.priorSize : this.league.auctionSheetSize,
      loss: loss ?? null,
    };
    writeStoredSheet(this.sheet);

    this.league = normaliseLeague({ ...this.league, auctionSheetSize: wanted.length });
    writeStoredLeague(this.league);
    this.restampStored();
    this.repriceInPlace();
    // persist() deletes the saved draft when there are no picks, so an empty
    // board announces without writing: the re-stamp above is what a saved
    // draft nobody has resumed yet needs.
    this.refreshMarketBoard();
    if (this.history.length) this.persist();
    else this.announce();
    return wanted.length;
  }

  /**
   * The shortest sheet that still prices sanely.
   *
   * The whole budget chases whatever is on the sheet, so a short one prices the
   * top of the board above what any single team holds — measured at 12 teams and
   * $200: twelve names put the best player at $238, or 119% of a budget, which
   * `validateBid` must reject for every team in the league. The board would then
   * carry a headline number nobody can legally bid.
   *
   * This is not a hypothetical setting somebody types. It is reached by accident
   * through the paste box: a surname-first export, or a defence block written in
   * nicknames, resolves a fraction of its names, and a sixty-name sheet quietly
   * becomes eighteen. Refusing here is what makes the import panel say so
   * instead. `normaliseLeague` also clamps the size up to the team count, so
   * anything below that would leave the stored size and the stored list
   * disagreeing about how many players are being auctioned.
   */
  private tooConcentrated(ids: readonly string[]): boolean {
    return this.previewSheet(ids).top > this.maxBiddablePrice();
  }

  /**
   * The most a player can be listed at and still be buyable: a whole budget.
   *
   * The whole budget chases whatever is on the sheet, so a list that is too
   * short prices its best player above what any single team holds — twelve names
   * put him at 119% of a budget — and `validateBid` must then reject that number
   * for every team in the league. The board would carry a headline price nobody
   * could legally bid.
   *
   * The bound is the budget rather than the 55% the pool's own tests assert,
   * because those two are answering different questions. 55% is a sanity check
   * on the *model*, over the whole board it was fitted to. A commissioner's list
   * is not the whole board: thirty good players beside thirty dollar players is
   * a real sheet, and the money genuinely does concentrate on the thirty. That
   * is expensive, not broken. Unbiddable is broken.
   *
   * Reaching it is not a setting anybody types. It happens through the paste box,
   * when a surname-first export or a defence block written in nicknames resolves
   * a fraction of its names and sixty quietly becomes eighteen.
   */
  maxBiddablePrice(): number {
    return this.league.budget;
  }

  /**
   * Drop the list.
   *
   * What happens to `auctionSheetSize` depends on whether anything was bought
   * under it, and the two cases are genuinely different.
   *
   * With picks on the board the size stays where the sheet put it. Those bids
   * were accepted under a zero reserve, and restoring a whole-board auction
   * would bring the reserve back and make picks already taken retrospectively
   * illegal. The room still auctions that many players; we simply no longer
   * know which, so pricing falls back to the best N by surplus.
   *
   * With an empty board there are no such bids, so keeping the size would strand
   * the owner in a partial auction they never chose. Removing a sheet has to be
   * an undo.
   */
  clearAuctionSheet(): void {
    if (!this.sheet.ids.length) return;
    const { priorSize } = this.sheet;
    this.sheet = EMPTY_SHEET();
    writeStoredSheet(this.sheet);

    if (!this.history.length && priorSize !== undefined) {
      this.league = normaliseLeague({ ...this.league, auctionSheetSize: priorSize });
      writeStoredLeague(this.league);
      this.restampStored();
    }

    this.repriceInPlace();
    // Removing a sheet moves the curve exactly as adding one does, so a derived
    // board has to be derived again here too.
    this.refreshMarketBoard();
    if (this.history.length) this.persist();
    else this.announce();
  }

  /**
   * A sheet player the room passed over: nobody bid even a dollar.
   *
   * Marked, never struck off. The snake phase decides the auction is finished
   * when every sheet player is gone, and one unsold player would otherwise hold
   * that condition false forever — stranding the app in an auction the room
   * left twenty minutes ago. Deleting him instead would shorten the sheet,
   * which moves `auctionSheetSize`, which re-prices everyone still for sale
   * mid-auction and makes the draft being played unreplayable. A marker settles
   * who is left without touching a price.
   */
  removeFromSheet(playerId: string): boolean {
    if (!this.sheet.ids.includes(playerId)) return false;
    if (this.sheet.unsold.includes(playerId)) return false;
    this.sheet = { ...this.sheet, unsold: [...this.sheet.unsold, playerId] };
    writeStoredSheet(this.sheet);
    this.announce();
    return true;
  }

  /** Put an unsold player back up: the room came back to him. */
  returnToSheet(playerId: string): boolean {
    if (!this.sheet.unsold.includes(playerId)) return false;
    this.sheet = { ...this.sheet, unsold: this.sheet.unsold.filter((id) => id !== playerId) };
    writeStoredSheet(this.sheet);
    this.announce();
    return true;
  }

  /**
   * Sheet players still to come: not sold, not passed over.
   *
   * Derived from the pick log and the sheet rather than counted anywhere, so it
   * cannot drift from either. This is the condition the snake phase begins on.
   */
  getSheetRemaining(): Player[] {
    if (!this.sheet.ids.length) return [];
    const unsold = new Set(this.sheet.unsold);
    const onSheet = new Set(this.sheet.ids);
    return this.players.filter(
      (player) => onSheet.has(player.id) && !player.isDrafted && !unsold.has(player.id)
    );
  }

  /**
   * What a sheet would do to the board, without committing to it.
   *
   * The import panel has to show the shift before it is applied: a sheet is the
   * largest single input to a price in this format, and a list that quietly
   * doubles what the top of the board costs should say so first. Facts only —
   * what each player costs now, and what he would cost then.
   */
  previewSheet(ids: readonly string[]): {
    top: number;
    median: number;
    bought: number;
    movers: Array<{ id: string; name: string; from: number; to: number }>;
  } {
    const entries = poolData.players as PoolEntry[];
    const wanted = new Set(ids);
    const mask = entries.map((entry) => wanted.has(entry.gsis));
    const size = mask.filter(Boolean).length;
    if (!size) return { top: 0, median: 0, bought: 0, movers: [] };

    const { priced } = pricePool(
      entries.map((entry) => ({
        position: entry.position,
        points: entry.projection.points,
        receptions: entry.projection.receptions,
      })),
      normaliseLeague({ ...this.league, auctionSheetSize: size }),
      { onSheet: mask }
    );

    const now = new Map(this.players.map((player) => [player.id, player.modelValue]));
    const movers = entries
      .map((entry, index) => ({
        id: entry.gsis,
        name: entry.name,
        from: now.get(entry.gsis) ?? 1,
        to: priced[index].auctionValue,
        on: mask[index],
      }))
      .filter((entry) => entry.on && entry.to !== entry.from)
      .sort((a, b) => b.to - b.from - (a.to - a.from))
      .slice(0, 5)
      .map(({ id, name, from, to }) => ({ id, name, from, to }));

    const sold = priced
      .map((entry) => entry.auctionValue)
      .filter((value) => value > 1)
      .sort((a, b) => b - a);

    return {
      top: sold[0] ?? 0,
      median: sold[Math.floor(sold.length / 2)] ?? 0,
      bought: sold.length,
      movers,
    };
  }

  /**
   * Re-stamp storage whose league differs *only* by the auction sheet size.
   *
   * A saved draft and the stash a reset left behind are both refused when their
   * stamp disagrees with the league in force, which is right: those bids bought
   * players at prices this league does not charge. A sheet import moves
   * `auctionSheetSize` and nothing else, so that refusal would throw away work
   * for no reason — hence the re-stamp.
   *
   * The condition is the whole point, and it was missing. Re-stamping whatever
   * is there rewrites stamps that were being *correctly* refused: reset a draft,
   * change the league from twelve teams to ten, import a sheet, and the stash is
   * silently re-stamped as a ten-team draft. Restoring it then replays picks at
   * budgets and prices they were never bid under, and drops the ones that no
   * longer fit without saying so. That stash is the undo-the-reset net added
   * after a real 192-pick draft caught Reset destroying an afternoon, and an
   * unrelated import must not be able to cut its only guard.
   */
  private restampStored(): void {
    for (const key of [AuctionDraftService.STORAGE_KEY, CLEARED_STORAGE_KEY]) {
      try {
        const raw = localStorage.getItem(key);
        if (!raw) continue;
        const saved = JSON.parse(raw) as Record<string, unknown>;
        if (!Array.isArray(saved.picks) || !saved.league) continue;

        // Everything but the sheet size has to already agree. Anything else is
        // a stamp that should go on being refused.
        const stamp = normaliseLeague(leagueShape(saved.league as Partial<LeagueShape>));
        const asIfResized = { ...stamp, auctionSheetSize: this.league.auctionSheetSize };
        if (!sameLeague(normaliseLeague(asIfResized), this.league)) continue;

        localStorage.setItem(key, JSON.stringify({ ...saved, league: this.league }));
      } catch {
        /* unreadable or unavailable — nothing to re-stamp */
      }
    }
  }

  /**
   * Rebuild the pool's valuations while keeping the draft that is under way.
   *
   * Rebuilding outright would drop who owns whom, so each player is rebuilt
   * from the pool and then has its draft state copied back on.
   */
  private repriceInPlace(): void {
    const state = new Map(
      this.players.map((player) => [
        player.id,
        {
          isDrafted: player.isDrafted,
          draftedBy: player.draftedBy,
          draftCost: player.draftCost,
          pickNumber: player.pickNumber,
        },
      ])
    );

    this.initializePlayers();

    for (const player of this.players) {
      const previous = state.get(player.id);
      if (!previous?.isDrafted) continue;
      player.isDrafted = true;
      player.draftedBy = previous.draftedBy;
      // Assigned only when there was a price. Writing `undefined` back would
      // leave the key present, and "has a draftCost of undefined" is one hop
      // from being treated as a cost of nothing by whoever reads it next.
      if (previous.draftCost != null) player.draftCost = previous.draftCost;
      player.pickNumber = previous.pickNumber;
    }
  }

  /**
   * Change the league, re-pricing the board.
   *
   * Every dollar value, replacement level and roster rule moves, so a draft in
   * progress cannot survive the change — its picks were made against prices
   * that no longer exist. The picks are cleared rather than silently
   * reinterpreted. Returns false when the shape would not change anything.
   */
  /**
   * Record that somebody has actually said what league this is.
   *
   * `setLeagueShape` returns early when nothing changed, and rightly so — it
   * clears the draft, and there is no reason to throw one away over a no-op.
   * But that means confirming the defaults exactly as they stand writes nothing,
   * and the first-run gate would ask again on every load. Writing the league it
   * already holds is the whole job: it costs nothing and it settles the
   * question.
   */
  confirmLeague(): void {
    writeStoredLeague(this.league);
    try {
      localStorage.setItem(LEAGUE_CONFIRMED_KEY, new Date().toISOString());
    } catch {
      /* storage unavailable — the gate simply will not have been recorded */
    }
  }

  setLeagueShape(next: LeagueShape): boolean {
    const wanted = normaliseLeague(next);
    if (sameLeague(wanted, this.league)) return false;
    this.league = wanted;
    this.draftedCount = 0;
    this.history = [];
    // Those picks were bid at prices this league does not charge, so putting
    // one back would build a roster nobody could have bought.
    this.undone = [];
    // Prices moved, so the saved copy is of a draft this league cannot replay.
    this.clearExportMark();
    this.initializePlayers();
    this.initializeTeams();
    writeStoredLeague(this.league);
    this.persist();
    return true;
  }

  /**
   * What a hypothetical purchase does to the rest of a roster.
   *
   * The number that actually decides a bid is not the price — it is what is left
   * per slot afterwards, and whether that still buys starters. This answers it
   * without committing anything.
   */
  simulateSpend(
    teamId: string,
    cost: number
  ): {
    remaining: number;
    slotsLeft: number;
    perSlot: number;
    /** Slots that must be filled at a dollar to stay legal. */
    minimumHold: number;
    /** True only when the amount is a real bid the reserve rules would allow. */
    /** Best player still on the board that the leftover budget could afford. */
    affordable: Player | null;
    legal: boolean;
  } | null {
    const team = this.teams.find((t) => t.id === teamId);
    if (!team) return null;

    const filled = Object.values(team.roster).reduce((a, b) => a + b, 0);
    const slotsLeft = Math.max(0, this.league.rosterSize - filled - 1);
    const remaining = team.remaining - cost;
    // Exactly what validateBid will hold back, read from the one place that
    // decides it rather than recomputed here.
    const minimumHold = this.spendableFor(team).held;
    const spendable = remaining - minimumHold;
    const affordable =
      spendable > 0
        ? (this.players
            .filter((p) => !p.isDrafted && p.id !== undefined && p.estimatedValue <= spendable)
            .sort((a, b) => b.projectedPoints - a.projectedPoints)[0] ?? null)
        : null;

    return {
      remaining,
      slotsLeft,
      perSlot: slotsLeft > 0 ? Math.max(0, remaining - minimumHold) / slotsLeft : 0,
      minimumHold,
      affordable,
      legal: remaining >= minimumHold && cost >= 1,
    };
  }

  /**
   * Where our board and the market's disagree, sorted by what the disagreement
   * is worth.
   *
   * It used to sort on `market.edge`, which is a difference of *ranks*, and
   * that put a $2 bench receiver the consensus has 160 places lower at the top
   * of a panel about bargains. A hundred and sixty places is a huge number and
   * a dollar of saving: below the top hundred or so, both boards are ranking
   * noise, and a rank gap there measures how little either of them knows
   * rather than how much money is on the table.
   *
   * The old arithmetic also did not do what its own comment said. It claimed
   * the expected price tracks the market rank rather than ours, then computed
   * that price from *our* value, and made up the difference with a bare
   * `edge * 0.12` — a constant nobody derived, converting ranks to dollars by
   * assertion. Consensus dollars are computable now, through the same module
   * that prices the consensus board, so there is one definition of what the
   * market thinks a player is worth and the fudge is gone.
   *
   * `gap` is therefore ours minus theirs in dollars: positive means we like
   * him more than the room does, which is what makes him cheap to buy and is
   * also — per the backtest — the direction in which our board is most often
   * the one that is wrong. Both facts belong to the same number, which is why
   * `modelTrust`'s caveats render on exactly these rows.
   *
   * Taken off `modelValue` rather than the live price, so applying the
   * consensus board does not then re-derive the disagreement against itself
   * and report that we agree with everybody about everything.
   */
  getBargains(limit = 24): Array<{
    player: Player;
    /** Ours minus the market's, in dollars. The sort key. */
    gap: number;
    /** The rank difference, kept because the panel prints both ranks. */
    edge: number;
    listed: number;
    projectedCost: number;
    saving: number;
  }> {
    const inflation = this.calculateMarketInflation();
    const market = consensusOverrides(
      this.players.map((player) => ({
        gsis: player.id,
        position: player.position,
        auctionValue: player.modelValue,
        consensusRank: player.market?.consensusRank ?? null,
      }))
    );
    return (
      this.players
        .filter((p) => !p.isDrafted && p.market?.consensusRank != null && this.forSale(p))
        .map((player) => {
          const listed = player.estimatedValue;
          const theirs = market[player.id]?.value ?? player.modelValue;
          // What the room will actually pay: their number, moved by the room's
          // inflation. Through the shared helper, so this is arithmetic with the
          // same adjusted price the stage and the table print rather than a
          // second rounding of it.
          const projectedCost = inflatedPrice(theirs, inflation);
          return {
            player,
            gap: player.modelValue - theirs,
            edge: player.market?.edge ?? 0,
            listed,
            projectedCost,
            saving: player.modelValue - projectedCost,
          };
        })
        // Tie-broken on our own number rather than the live one, for the same
        // reason the gap is: off `listed`, applying the consensus board would
        // silently reshuffle every row whose gap ties with another.
        .sort((a, b) => b.gap - a.gap || b.player.modelValue - a.player.modelValue)
        .slice(0, limit)
    );
  }

  /**
   * Every pick so far, grouped for the league board.
   *
   * `cost` is null for a snake pick rather than 0, and the phase travels with
   * it, because the board has to be able to print "—" where there was no price.
   * A grid of `$0` cells reads as a room that bought a hundred and forty
   * players for nothing, which is the opposite of what happened.
   *
   * `index` is where the pick sits in the log, and it is here because the grid
   * is where a mistake gets noticed and so is where it should be correctable.
   * It is read off the log rather than inferred from `pickNumber`: the two
   * agree today, and a cell that edits the wrong entry because they stopped
   * agreeing is the worst thing this feature could do.
   */
  getDraftBoard(): Array<{
    team: Team;
    picks: Array<{
      player: Player;
      cost: number | null;
      phase: DraftPhase;
      pickNumber: number;
      index: number;
    }>;
  }> {
    const entries = new Map(
      this.history.map((pick, index) => [pick.playerId, { phase: pick.phase, index }])
    );
    return this.teams.map((team) => ({
      team,
      picks: this.players
        .filter((p) => p.draftedBy === team.id)
        .map((p) => ({
          player: p,
          cost: p.draftCost ?? null,
          phase: entries.get(p.id)?.phase ?? 'auction',
          pickNumber: p.pickNumber ?? 0,
          index: entries.get(p.id)?.index ?? -1,
        }))
        .sort((a, b) => a.pickNumber - b.pickNumber),
    }));
  }

  canUndo(): boolean {
    return this.history.length > 0;
  }

  private updateTeamMetrics(team: Team): void {
    const teamPlayers = this.players.filter((p) => p.draftedBy === team.id);

    // Calculate strength score (average projected points)
    team.strengthScore =
      teamPlayers.length > 0
        ? teamPlayers.reduce((sum, p) => sum + p.projectedPoints, 0) / teamPlayers.length
        : 0;

    // Calculate risk score (average injury risk)
    const riskValues = { LOW: 1, MEDIUM: 2, HIGH: 3 };
    team.riskScore =
      teamPlayers.length > 0
        ? teamPlayers.reduce((sum, p) => sum + riskValues[p.injuryRisk], 0) / teamPlayers.length
        : 0;

    // Players beyond the starting lineup. This read from its own QB1/RB2/WR2
    // table, which disagreed with the QB1/RB2/WR3 one urgency used — a third
    // receiver counted as bench depth and as a starter at the same time.
    team.depthScore = Object.entries(team.roster).reduce((total, [pos, count]) => {
      const starting = this.league.startingLineup[pos as PlayerPosition] ?? 0;
      return total + Math.max(0, count - starting);
    }, 0);

    // Calculate injury insurance (handcuff value)
    team.injuryInsurance = teamPlayers.reduce((sum, p) => sum + (p.handcuffValue ?? 0), 0) / 100;
  }

  /**
   * What this player should cost this team, right now.
   *
   * Three real forces move a price away from the list value: how much money is
   * still chasing how much value (inflation), how badly this team still needs
   * the position (need), and how little of the position is left (scarcity).
   * Nothing here is invented — each one is read off the current draft state.
   */
  generateDraftAnalytics(playerId: string, teamId: string): DraftAnalytics {
    const player = this.players.find((p) => p.id === playerId);
    const team = this.teams.find((t) => t.id === teamId);
    if (!player || !team) throw new Error('Player or team not found');

    const marketInflation = this.calculateMarketInflation();
    const needMultiplier = this.calculateNeedMultiplier(player.position, team);
    const positionScarcity = this.calculatePositionScarcity(player.position);

    const adjustedValue =
      player.baseValue * marketInflation * needMultiplier * (1 + positionScarcity * 0.15);

    // Injury and age history discount what we are willing to commit.
    const riskFactor =
      (player.injuryRisk === 'HIGH' ? 0.88 : player.injuryRisk === 'MEDIUM' ? 0.95 : 1) *
      (player.ageRisk === 'HIGH' ? 0.9 : player.ageRisk === 'MEDIUM' ? 0.96 : 1);
    const riskAdjustedValue = adjustedValue * riskFactor;

    // Through spendableFor, not a second copy of the same arithmetic. The
    // rival ceilings the room now shows lean on this number, and two hand-rolled
    // repeats of a reserve rule that claims one owner is how they drift.
    const spendable = Math.max(1, this.spendableFor(team).spendable);

    const targetBid = Math.max(1, Math.round(riskAdjustedValue));
    const maxBid = Math.max(1, Math.min(Math.round(riskAdjustedValue * 1.15), spendable));
    const openingBid = Math.max(1, Math.round(targetBid * 0.6));

    return {
      baseValue: player.baseValue,
      adjustedValue: Math.round(adjustedValue),
      maxBid,
      openingBid,
      targetBid,
      // The first dollar you should not spend.
      walkAwayPoint: maxBid + 1,
      needMultiplier: Math.round(needMultiplier * 100) / 100,
      scarcityFactor: Math.round(positionScarcity * 100) / 100,
      confidenceLevel: this.calculateConfidenceLevel(player),
      marketInflation: Math.round(marketInflation * 100) / 100,
      positionScarcity: Math.round(positionScarcity * 100) / 100,
      valueOverBaseline: player.valueOverReplacement,
      riskAdjustedValue: Math.round(riskAdjustedValue),
      optimalBidRange: [openingBid, maxBid],
      injuryAdjustment: Math.round((1 - riskFactor) * 100) / 100,
      ageAdjustment: player.ageRisk === 'LOW' ? 0 : player.ageRisk === 'MEDIUM' ? 0.04 : 0.1,
      competitionRisk: player.competitionLevel === 'LOCKED_STARTER' ? 0 : 0.15,
      rosterId: team.id,
    };
  }

  /**
   * Dollars still available divided by the value still on the board. Above 1.0
   * the room is going to overpay for what is left; below it, bargains.
   */
  private calculateMarketInflation(): number {
    /*
     * One definition, with its workings attached.
     *
     * This used to compute the ratio here and the market panel printed it with
     * nothing behind it. A multiplier nobody can interrogate is not an edge, so
     * the inputs — money left, value left, the clamp, the snake freeze — are all
     * reported by `getInflationBasis`, and this reads the same field the board
     * reads rather than repeating the arithmetic beside it.
     */
    return this.getInflationBasis().inflation;
  }

  /**
   * How urgently this team still needs the position.
   *
   * An empty slot early is not urgent — there is a whole draft left to fill it.
   * The premium therefore grows with how much of the position is already gone,
   * which is what actually makes a hole expensive.
   */
  private calculateNeedMultiplier(position: string, team: Team): number {
    // Derived from the league's own lineup, so a superflex or a 3-WR league
    // makes the positions it actually starts urgent, and a flex counts for
    // every position that could fill it.
    const unfilled = unfilledSlotsFor(position as PlayerPosition, team.roster, this.league);
    const gone = this.calculatePositionScarcity(position);
    return 1 + Math.min(0.45, unfilled * 0.18 * gone);
  }

  /** Share of the position's startable players already off the board. */
  private calculatePositionScarcity(position: string): number {
    const startable = this.players.filter((p) => p.position === position && this.forSale(p));
    if (!startable.length) return 0;
    const gone = startable.filter((p) => p.isDrafted).length;
    return gone / startable.length;
  }

  /** How much of this player we have actually seen, on a 0-100 scale. */
  private calculateConfidenceLevel(player: Player): number {
    const games = player.lastSeasonGames ?? 0;
    const sample = Math.min(1, games / 17);
    const steadiness = (player.consistency ?? 5) / 10;
    return Math.round((sample * 0.6 + steadiness * 0.4) * 100);
  }

  isDraftComplete(): boolean {
    return this.draftedCount >= 60;
  }

  searchPlayers(query: string): Player[] {
    if (!query) return this.players;
    return this.players.filter(
      (p) =>
        p.name.toLowerCase().includes(query.toLowerCase()) ||
        p.position.toLowerCase().includes(query.toLowerCase()) ||
        p.team.toLowerCase().includes(query.toLowerCase())
    );
  }

  getPlayerAnalytics(playerId: string, teamId: string = 'team-1'): DraftAnalytics {
    return this.generateDraftAnalytics(playerId, teamId);
  }

  getDraftedPlayers(): Player[] {
    return this.players.filter((p) => p.isDrafted);
  }

  getAvailablePlayers(): Player[] {
    return this.players.filter((p) => !p.isDrafted);
  }

  resetDraft(): void {
    // Stash before clearing, so the reset can be taken back.
    if (this.history.length) {
      try {
        localStorage.setItem(
          CLEARED_STORAGE_KEY,
          JSON.stringify({
            clearedAt: new Date().toISOString(),
            league: this.league,
            budgets: this.teams.map((t) => ({ id: t.id, budget: t.budget })),
            picks: this.history,
          })
        );
      } catch {
        /* storage unavailable — the reset is simply not undoable */
      }
    }

    this.players.forEach((p) => {
      p.isDrafted = false;
      delete p.draftedBy;
      delete p.draftCost;
      delete p.pickNumber;
    });
    this.draftedCount = 0;
    this.history = [];
    // Redo is the small net and the stash above is the big one. Leaving undone
    // picks here would let "r" splice a pick from the cleared draft into an
    // empty board, which is neither draft.
    this.undone = [];
    // The mark described a draft that no longer exists. Left in place, a fresh
    // draft shorter than the old one reported a single unsaved pick — the calm
    // end of the scale — for work that has never left the browser.
    this.clearExportMark();
    this.teams.forEach((team) => {
      team.spent = 0;
      team.remaining = team.budget;
      team.roster = EMPTY_ROSTER();
      team.projectedTotal = 0;
      // Derived metrics too: leaving these behind makes a reset draft report
      // the strength and risk of the roster it just threw away.
      team.strengthScore = 0;
      team.riskScore = 0;
      team.depthScore = 0;
      team.injuryInsurance = 0;
    });
    this.persist();
  }

  // -------------------------------------------------------------------------
  // persistence
  //
  // Only the picks are stored: replaying them rebuilds every derived number, so
  // a saved draft can never disagree with the current valuation logic.
  // -------------------------------------------------------------------------

  /**
   * Watch for changes that reached storage.
   *
   * Deliberately carries nothing: a listener is being told the draft moved, not
   * what it moved to. Whatever it needs, it reads back from the engine, which
   * is the same rule that keeps the pick log the only shared fact.
   */
  addChangeListener(listener: () => void): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  /**
   * The single-listener form, kept because one caller reads naturally as one.
   *
   * It cannot stay the only form: a second window follows the draft through
   * it already, and anything else that wants to react to a pick — a save, a
   * sync, a refresh — would silently take the slot and stop the first from
   * ever firing again. A Set is the seam; this is a convenience over it.
   */
  setChangeListener(listener: (() => void) | null): void {
    this.listeners.clear();
    if (listener) this.listeners.add(listener);
  }

  /**
   * Put a saved pick log back on the board, and say how much of it landed.
   *
   * Three callers replay — resuming this browser's draft, taking back a reset,
   * and loading a file — and they were three copies of the same loop. That is
   * one loop three chances to diverge, and a pick that replays differently
   * depending on which door it came through is a draft that disagrees with
   * itself. Picks that no longer validate are counted, never dropped quietly.
   */
  private replay(picks: ReadonlyArray<Partial<DraftPick>>): number {
    let restored = 0;
    for (const pick of picks) {
      if (!pick.playerId || !pick.teamId) continue;
      // A pick log written before the snake existed carries no phase, and every
      // pick in it was an auction buy — which is what the missing field means,
      // not a value to guess at.
      const ok =
        pick.phase === 'snake'
          ? this.applySnakePick(pick.playerId, pick.teamId, pick.slot)
          : this.draftPlayer(pick.playerId, pick.teamId, pick.cost ?? 0);
      if (ok) restored++;
    }
    return restored;
  }

  private announce(): void {
    if (this.applyingRemote) return;
    for (const listener of this.listeners) listener();
  }

  /**
   * Rebuild from what another window wrote.
   *
   * The whole state is re-derived from storage rather than patched, because a
   * patch would need to know what changed and the channel deliberately does not
   * say. Rebuilding cannot drift; a patch could.
   */
  reloadFromStorage(): void {
    this.applyingRemote = true;
    try {
      this.league = normaliseLeague(readStoredLeague());
      this.overrides = readStoredOverrides();
      // The sheet decides what the money is buying, so it has to be back in
      // hand before the board is priced rather than after it.
      this.sheet = readStoredSheet();
      // The order decides who the second screen says is on the clock, and a
      // window that kept the old one would put a different name up.
      this.snakeOrder = readStoredSnakeOrder();
      const stored = readStoredTeams();
      this.teamNames = stored.names ?? {};
      this.myTeamId = stored.mine ?? null;
      this.draftedCount = 0;
      this.history = [];
      // Whatever this window had taken back, the window that just wrote has
      // moved on from. Redo is a private note about what one person did here,
      // never a shared fact, so it does not survive being told the draft moved.
      this.undone = [];
      this.initializePlayers();
      this.initializeTeams();
      // Replays the pick log the other window just wrote. A cleared draft
      // leaves nothing to restore, which is the correct empty board.
      this.restore();
    } finally {
      this.applyingRemote = false;
    }
  }

  private persist(): void {
    try {
      // Emptying the draft is a change like any other. This used to `return`
      // here, which skipped the announcement below — so a second window
      // followed picks but never followed an undo back to zero, a reset, or a
      // league change (which clears the picks and so lands on this branch).
      if (!this.history.length) {
        localStorage.removeItem(AuctionDraftService.STORAGE_KEY);
      } else {
        localStorage.setItem(
          AuctionDraftService.STORAGE_KEY,
          JSON.stringify({
            version: 2,
            savedAt: new Date().toISOString(),
            // Stamped, not to be replayed from, but so a pick log cannot be
            // reinterpreted under a league it was never bid in. Absent on saves
            // written before leagues were configurable, which were all default.
            league: this.league,
            budgets: this.teams.map((t) => ({ id: t.id, budget: t.budget })),
            picks: this.history,
          })
        );
      }
    } catch {
      /* storage unavailable (private mode, quota) — the draft simply won't resume */
    }
    this.announce();
  }

  /** Replays a saved draft. Returns how many picks were restored. */
  restore(): number {
    let saved: {
      version?: number;
      league?: LeagueShape;
      budgets?: Array<{ id: string; budget: number }>;
      picks?: DraftPick[];
    } | null = null;
    try {
      const raw = localStorage.getItem(AuctionDraftService.STORAGE_KEY);
      saved = raw ? JSON.parse(raw) : null;
    } catch {
      saved = null;
    }
    if (!saved?.picks?.length || saved.version !== 2) return 0;

    // Those bids bought players at prices this league does not charge. Replaying
    // them would produce a roster nobody could have afforded, so decline.
    const savedLeague = saved.league ? normaliseLeague(leagueShape(saved.league)) : POOL_LEAGUE;
    if (!sameLeague(savedLeague, this.league)) return 0;

    // Emptying the board to replay onto it, not throwing a draft away. The
    // difference matters to the export mark: resetDraft forgets it, because the
    // log it described is gone — but a reload replays that very log, so the
    // mark still describes exactly what is about to be on the board. Clearing
    // it here made every refresh report the whole draft as unsaved.
    const mark = this.mark;
    this.resetDraft();
    this.mark = mark;
    if (mark) writeStoredMark(mark);
    for (const { id, budget } of saved.budgets ?? []) this.updateTeamBudget(id, budget);

    const restored = this.replay(saved.picks);
    return restored;
  }

  /**
   * How many picks a reset threw away, if one can still be taken back.
   *
   * Only offered while the board is empty: once somebody drafts again the
   * cleared draft is genuinely history, and restoring it would silently
   * replace work done since.
   */
  clearedPickCount(): number {
    if (this.history.length) return 0;
    try {
      const raw = localStorage.getItem(CLEARED_STORAGE_KEY);
      const saved = raw ? (JSON.parse(raw) as { league?: LeagueShape; picks?: unknown[] }) : null;
      if (!saved?.picks?.length) return 0;
      // Prices moved on if the league changed; those bids no longer make sense.
      const league = saved.league ? normaliseLeague(leagueShape(saved.league)) : POOL_LEAGUE;
      return sameLeague(league, this.league) ? saved.picks.length : 0;
    } catch {
      return 0;
    }
  }

  /** Put back the draft the last reset cleared. Returns how many picks returned. */
  restoreClearedDraft(): number {
    if (this.history.length) return 0;
    let saved: {
      league?: LeagueShape;
      budgets?: Array<{ id: string; budget: number }>;
      picks?: DraftPick[];
    } | null = null;
    try {
      const raw = localStorage.getItem(CLEARED_STORAGE_KEY);
      saved = raw ? JSON.parse(raw) : null;
    } catch {
      saved = null;
    }
    if (!saved?.picks?.length) return 0;

    const league = saved.league ? normaliseLeague(leagueShape(saved.league)) : POOL_LEAGUE;
    if (!sameLeague(league, this.league)) return 0;

    for (const { id, budget } of saved.budgets ?? []) this.updateTeamBudget(id, budget);
    const restored = this.replay(saved.picks);
    try {
      localStorage.removeItem(CLEARED_STORAGE_KEY);
    } catch {
      /* nothing to clean up */
    }
    return restored;
  }

  // -------------------------------------------------------------------------
  // how exposed the record is
  //
  // On the night there is no server, no account and no second machine: the
  // draft is a pick log in one browser profile, and the only copy of an
  // afternoon is the tab it is being played in. The file and the clipboard are
  // the ways out; forgetting to use one while an auction is running is the
  // failure that actually happens. So the app counts rather than reminds.
  // -------------------------------------------------------------------------

  /**
   * A cheap, stable summary of the pick log.
   *
   * FNV-1a over the log's own JSON, prefixed with its length so two logs of
   * different sizes can never collide. It answers one question — is this the
   * draft that went out — which a pick count alone cannot: undo a pick and
   * re-enter it at the right price and the count is unchanged while the record
   * is not.
   */
  private fingerprint(): string {
    const text = JSON.stringify(this.history);
    let hash = 2166136261;
    for (let i = 0; i < text.length; i++) {
      hash ^= text.charCodeAt(i);
      hash = Math.imul(hash, 16777619);
    }
    return `${this.history.length}:${(hash >>> 0).toString(36)}`;
  }

  /**
   * Record that the whole draft has just left this browser.
   *
   * Called by the two acts that put a copy somewhere the owner can point at: a
   * file, and the clipboard. The optional server's autosave deliberately does
   * not call it. That is not an oversight — the server is an overlay that is
   * usually not running, and this counter measures what the owner is holding
   * rather than what some process managed on his behalf. A number that goes
   * quiet because of a backup nobody remembers making is a number that lies in
   * the one direction that costs an afternoon.
   */
  markExported(kind: ExportMark['kind'], of: ExportSnapshot = this.snapshotMark()): ExportMark {
    this.mark = { savedAt: new Date().toISOString(), kind, ...of };
    writeStoredMark(this.mark);
    return this.mark;
  }

  /**
   * The log as it stands, to be stamped later against the text that left.
   *
   * Saving is not instantaneous: the artifact's downloads capability puts a
   * confirmation in front of a person, and the clipboard can wait on a
   * permission prompt. Stamping after the await marks the log as it is *then*,
   * so a pick recorded while the save was in flight was recorded as saved. The
   * caller takes this the moment it calls exportDraft and hands it back after,
   * so the stamp describes the payload rather than the present.
   */
  snapshotMark(): ExportSnapshot {
    return { picks: this.history.length, fingerprint: this.fingerprint() };
  }

  /** When the draft last left this browser, if it ever has. */
  getExportMark(): ExportMark | null {
    return this.mark;
  }

  /**
   * How far the record has moved since the last copy of it left this browser.
   *
   * Zero when the copy is the draft on the board, and zero on an empty board —
   * there is nothing to lose before the first pick, and a warning at that point
   * is a warning nobody will read at pick forty. With no copy ever made the
   * answer is the whole draft, which is exactly the exposure.
   *
   * Between those, the honest reading is a floor rather than an exact count: a
   * log that differs from the saved one has moved by at least one change, and
   * an undo followed by a re-entry moves it twice while leaving the length
   * alone. It says "at least this far behind", and it is never behind by less.
   */
  picksSinceExport(): number {
    if (!this.history.length) return 0;
    if (!this.mark) return this.history.length;
    if (this.mark.fingerprint === this.fingerprint()) return 0;
    // A mark describing a longer log than the one on the board cannot be a copy
    // of any part of it — a reset, a league change or a heavy correction has
    // been through. The whole board is unsaved, and subtracting would have
    // reported exactly 1: the calm end of the scale, for a draft that has never
    // left the browser at all. This is the one direction the number must never
    // be wrong in.
    if (this.mark.picks > this.history.length) return this.history.length;
    return Math.max(1, this.history.length - this.mark.picks);
  }

  /** Forget the mark, for when the log it describes is thrown away entirely. */
  private clearExportMark(): void {
    this.mark = null;
    try {
      localStorage.removeItem(EXPORT_MARK_KEY);
    } catch {
      /* storage unavailable — the mark was never durable anyway */
    }
  }

  /**
   * The draft as a file somebody can keep.
   *
   * localStorage is one browser profile on one machine: a cleared cache, a
   * borrowed laptop or a dead battery loses the afternoon. This is the same
   * thing `persist()` writes, plus the league it was bid under, so a draft can
   * be carried somewhere else and picked up mid-auction.
   */
  exportDraft(): string {
    return JSON.stringify(
      {
        kind: 'draft-vault-draft',
        version: 1,
        savedAt: new Date().toISOString(),
        league: this.league,
        // The sheet travels beside the league because it is now part of what
        // set the prices: the same picks under the same league but a different
        // list describe a different auction. A draft carried to a backup laptop
        // has to price identically, not approximately.
        auctionSheet: this.sheet,
        // The snake order travels too. It sets nothing about a price, so a file
        // without one still replays every pick correctly — but a backup laptop
        // that came up mid-snake with the default team order would put the
        // wrong team on the clock, which is the one thing the room in front of
        // it cannot check against the app.
        snakeOrder: this.snakeOrder,
        // Who the teams are travels with the draft: a pick log full of
        // "Team 7" is a worse record of the night than it needs to be.
        teamNames: this.teamNames,
        myTeamId: this.myTeamId,
        budgets: this.teams.map((t) => ({ id: t.id, budget: t.budget })),
        picks: this.history,
      },
      null,
      2
    );
  }

  /**
   * Load a draft from a file, replacing whatever is on the board.
   *
   * The league travels with the picks and is adopted, because prices are
   * meaningless without it — a draft bid in a ten-team league does not describe
   * a roster anybody could buy in a twelve-team one. Picks that no longer
   * validate are counted rather than silently dropped.
   */
  importDraft(
    text: string
  ): { ok: true; restored: number; skipped: number } | { ok: false; reason: string } {
    let saved: {
      kind?: string;
      league?: LeagueShape;
      auctionSheet?: Partial<StoredSheet>;
      snakeOrder?: unknown;
      teamNames?: Record<string, string>;
      myTeamId?: string | null;
      budgets?: Array<{ id: string; budget: number }>;
      picks?: DraftPick[];
    };
    try {
      saved = JSON.parse(text);
    } catch {
      return { ok: false, reason: 'That file is not a saved draft — it is not readable as JSON.' };
    }

    if (!saved || saved.kind !== 'draft-vault-draft') {
      return { ok: false, reason: 'That file was not saved by Draft Vault.' };
    }
    if (!Array.isArray(saved.picks)) {
      return { ok: false, reason: 'That draft file has no picks in it.' };
    }

    this.league = saved.league ? normaliseLeague(leagueShape(saved.league)) : this.league;
    writeStoredLeague(this.league);
    // A file with no sheet replaces the board with a board that has none: the
    // import replaces what is here rather than merging into it, and a stale
    // list left behind would price this draft as no draft was ever priced.
    this.sheet = Array.isArray(saved.auctionSheet?.ids)
      ? {
          ids: saved.auctionSheet.ids.filter((id): id is string => typeof id === 'string'),
          unsold: Array.isArray(saved.auctionSheet.unsold)
            ? saved.auctionSheet.unsold.filter((id): id is string => typeof id === 'string')
            : [],
          // Carried through, because dropping it silently re-armed the bug its
          // own doc comment describes: with no prior size, removing the sheet
          // on the restored machine leaves auctionSheetSize pinned forever, and
          // the board is stuck in a partial auction nobody chose. Rare when a
          // restore meant a USB stick; routine once a server saves a version
          // per pick and the answer to any mishap is "load it on the backup".
          priorSize:
            typeof saved.auctionSheet.priorSize === 'number' ||
            saved.auctionSheet.priorSize === null
              ? saved.auctionSheet.priorSize
              : undefined,
          // Carried for the same reason: the paste it was measured from is
          // gone, so a restore that dropped it would report a lossy sheet as a
          // clean one on the machine that has to finish the draft.
          loss: typeof saved.auctionSheet.loss === 'number' ? saved.auctionSheet.loss : null,
        }
      : EMPTY_SHEET();
    writeStoredSheet(this.sheet);
    // A file saved before the snake existed carries no order, and the empty
    // list is the correct reading of that: fall back to the team order.
    this.snakeOrder = Array.isArray(saved.snakeOrder)
      ? saved.snakeOrder.filter((id): id is string => typeof id === 'string')
      : [];
    writeStoredSnakeOrder(this.snakeOrder);
    if (saved.teamNames) this.teamNames = saved.teamNames;
    if (saved.myTeamId !== undefined) this.myTeamId = saved.myTeamId;
    writeStoredTeams({ names: this.teamNames, mine: this.myTeamId });
    this.draftedCount = 0;
    this.history = [];
    // A file replaces the board, so an undone pick from the draft it replaced
    // belongs to a draft that is no longer here.
    this.undone = [];
    this.initializePlayers();
    this.initializeTeams();

    for (const { id, budget } of saved.budgets ?? []) this.updateTeamBudget(id, budget);

    const restored = this.replay(saved.picks);
    this.persist();
    const skipped = saved.picks.length - restored;
    // A draft that came out of a file is a draft that demonstrably exists in
    // one, so the exposure counter starts from zero rather than warning about
    // picks that are already safely on disk. Only when every pick replayed:
    // if any were dropped the file and the board are different drafts, and the
    // file is not a copy of what is now being played.
    if (!skipped) this.markExported('file');
    return { ok: true, restored, skipped };
  }

  /** Whether a resumable draft is sitting in storage. */
  /**
   * Whether anybody has ever said what league this is.
   *
   * With nothing stored the engine falls back to the league the *pool* was
   * built for, which is a valid league and is almost certainly not yours: it is
   * full PPR with no flex, because that is what nflverse scores and what the
   * builder had to pick. Every price on the board is computed from it, so a
   * fresh browser on draft night prices a hundred-catch receiver about fifty
   * points too high — silently, and on exactly the position group the auction
   * is about. Making scoring configurable did not fix that; it only made the
   * fix reachable.
   */
  static hasStoredLeague(): boolean {
    try {
      return !!localStorage.getItem(LEAGUE_CONFIRMED_KEY);
    } catch {
      // Storage unavailable: asking on every load would be worse than not
      // asking at all, and there would be nowhere to record the answer.
      return true;
    }
  }

  static hasSavedDraft(): boolean {
    try {
      return !!localStorage.getItem(AuctionDraftService.STORAGE_KEY);
    } catch {
      return false;
    }
  }

  private static readonly STORAGE_KEY = 'draft-vault:auction-draft:v2';

  getHistory(): ReadonlyArray<DraftPick> {
    return this.history;
  }

  getValueGrade(estimatedValue: number, actualCost: number): string {
    const ratio = actualCost / estimatedValue;
    if (ratio <= 0.8) return 'A+';
    if (ratio <= 0.9) return 'A';
    if (ratio <= 1.0) return 'B+';
    if (ratio <= 1.1) return 'B';
    if (ratio <= 1.2) return 'C';
    return 'D';
  }

  getProgressPercentage(): number {
    return (this.draftedCount / 60) * 100;
  }

  updateTeamBudget(teamId: string, budget: number): void {
    const team = this.teams.find((t) => t.id === teamId);
    if (!team) return;
    if (!Number.isFinite(budget)) return;
    // A budget below what the team already committed would leave it with
    // negative money to spend, so it cannot go under the amount already spent.
    team.budget = Math.max(team.spent, Math.round(budget));
    team.remaining = team.budget - team.spent;
  }

  getAuctionPlayers(): Player[] {
    return this.players;
  }

  getSnakeDraftPlayers(): SnakeDraftPlayer[] {
    // Return empty array since snake draft uses separate database
    return [];
  }
}
